import json
w0={int(k):v for k,v in json.load(open('/tmp/t/w0.json')).items()}
props3={int(k):v for k,v in json.load(open('/tmp/t/props3.json')).items()}
props4={int(k):v for k,v in json.load(open('/tmp/t/props4.json')).items()}
EP=set(c for c,v in props4.items() if v[1])       # emoji presentation (single char sets state)
TP=set(c for c,v in props3.items() if v['stv'])   # text presentation (VS16 sets state)
SKIN=set(range(0x1F3FB,0x1F400))
RI=set(range(0x1F1E6,0x1F200))
props={int(k):v for k,v in json.load(open('/tmp/t/props.json')).items()}
U2=set(c for c,v in props.items() if v[2] in (0,1))  # emoji modifier base
VS16=0xFE0F; ZWJ=0x200D
def width(chars):
    total=0; state=False; prev=None; prev_w=0
    n=len(chars); i=0
    while i<n:
        c=chars[i]
        if c==VS16:
            if prev is not None and prev in TP:
                if prev_w==1: total+=1
                state=True
            else:
                state=False
            prev_w=0; prev=c; i+=1; continue
        if c in SKIN:
            if prev is not None and prev in U2:
                if prev_w==1: total+=1
                w=0
            else:
                w=2
            state=True; total+=w; prev_w=w; prev=c; i+=1; continue
        if c==ZWJ:
            if state:
                j=i+1
                if j<n:
                    nx=chars[j]
                    if nx in EP:
                        total+=0; prev=nx; prev_w=0; state=True; i=j+1; continue
                    if nx in TP and j+1<n and chars[j+1]==VS16:
                        total+=0; prev=chars[j+1]; prev_w=0; state=True; i=j+2; continue
                    if nx in U2 and j+1<n and chars[j+1] in SKIN:
                        total+=0; prev=chars[j+1]; prev_w=0; state=True; i=j+2; continue
                    if nx in SKIN:
                        total+=0; prev=nx; prev_w=0; state=True; i=j+1; continue
                    if nx in RI and j+1<n and chars[j+1] in RI:
                        total+=0; prev=chars[j+1]; prev_w=0; state=True; i=j+2; continue
            state=False; prev=c; prev_w=0; i+=1; continue
        w=w0.get(c,1)
        state=(c in EP)
        total+=w; prev_w=w; prev=c; i+=1
    return total
