use crate::tables::{EMOJI_PRESENTATION, MODIFIER_BASE, TEXT_PRESENTATION, WIDE, WIDTH3, ZERO_WIDTH};

const VS16: u32 = 0xFE0F;
const ZWJ: u32 = 0x200D;

fn in_table(table: &[(u32, u32)], cp: u32) -> bool {
    let mut lo = 0usize;
    let mut hi = table.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b) = table[mid];
        if cp < a {
            hi = mid;
        } else if cp > b {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

/// Base width of a single character (ignores any surrounding context).
pub fn base_width(c: char) -> usize {
    let cp = c as u32;
    if cp == 6104 {
        return 3;
    }
    if in_table(ZERO_WIDTH, cp) {
        0
    } else if in_table(WIDE, cp) {
        2
    } else {
        1
    }
}

fn is_zero(c: char) -> bool {
    in_table(ZERO_WIDTH, c as u32)
}
fn is_wide(c: char) -> bool {
    let cp = c as u32;
    cp == 6104 || in_table(WIDE, cp)
}
fn is_emoji_presentation(c: char) -> bool {
    in_table(EMOJI_PRESENTATION, c as u32)
}
fn is_text_presentation(c: char) -> bool {
    in_table(TEXT_PRESENTATION, c as u32)
}
fn is_modifier_base(c: char) -> bool {
    in_table(MODIFIER_BASE, c as u32)
}
fn is_skin(c: char) -> bool {
    matches!(c as u32, 0x1F3FB..=0x1F3FF)
}
fn is_ri(c: char) -> bool {
    matches!(c as u32, 0x1F1E6..=0x1F1FF)
}

/// Compute the display width of `chars`, replicating the behaviour of the
/// upstream implementation (including emoji presentation sequences).
pub fn str_width(chars: &[char]) -> usize {
    let mut total = 0usize;
    // true when the previously emitted cluster is a wide emoji presentation
    let mut wide = false;
    let mut prev: Option<char> = None;
    let mut prev_w: usize = 0;
    let mut i = 0usize;
    let n = chars.len();
    while i < n {
        let c = chars[i];
        if c as u32 == VS16 {
            match prev {
                Some(p) if is_text_presentation(p) => {
                    if prev_w == 1 {
                        total += 1;
                    }
                    wide = true;
                }
                _ => wide = false,
            }
            prev = Some(c);
            prev_w = 0;
            i += 1;
            continue;
        }
        if is_skin(c) {
            let w = match prev {
                Some(p) if is_modifier_base(p) => {
                    if prev_w == 1 {
                        total += 1;
                    }
                    0
                }
                _ => 2,
            };
            wide = true;
            total += w;
            prev = Some(c);
            prev_w = w;
            i += 1;
            continue;
        }
        if c as u32 == ZWJ {
            let mut consumed = false;
            if wide {
                if let Some(&nx) = chars.get(i + 1) {
                    if is_emoji_presentation(nx) {
                        total += 0;
                        prev = Some(nx);
                        prev_w = 0;
                        wide = true;
                        i += 2;
                        consumed = true;
                    } else if is_text_presentation(nx)
                        && matches!(chars.get(i + 2), Some(&nc) if nc as u32 == VS16)
                    {
                        prev = Some(VS16 as char);
                        prev_w = 0;
                        wide = true;
                        i += 3;
                        consumed = true;
                    } else if is_modifier_base(nx)
                        && matches!(chars.get(i + 2), Some(&nc) if is_skin(nc))
                    {
                        prev = chars[i + 2];
                        prev_w = 0;
                        wide = true;
                        i += 3;
                        consumed = true;
                    } else if is_skin(nx) {
                        prev = Some(nx);
                        prev_w = 0;
                        wide = true;
                        i += 2;
                        consumed = true;
                    } else if is_ri(nx) && matches!(chars.get(i + 2), Some(&nc) if is_ri(nc)) {
                        prev = chars[i + 2];
                        prev_w = 0;
                        wide = true;
                        i += 3;
                        consumed = true;
                    }
                }
            }
            if !consumed {
                wide = false;
                prev = Some(c);
                prev_w = 0;
                i += 1;
            }
            continue;
        }
        // regular character
        let w = if is_zero(c) {
            0
        } else if is_wide(c) {
            2
        } else {
            1
        };
        // "\r\n" is counted as a single column
        if c == '\r' && matches!(chars.get(i + 1), Some(&nc) if nc == '\n') {
            total += 1;
            prev = Some('\n');
            prev_w = 1;
            wide = false;
            i += 2;
            continue;
        }
        total += w;
        wide = is_emoji_presentation(c);
        prev = Some(c);
        prev_w = w;
        i += 1;
    }
    total
}

pub fn width(s: &str) -> usize {
    let chars: Vec<char> = s.chars().collect();
    str_width(&chars)
}
