fn read_record(&mut self) -> Result<Option<Vec<Vec<u8>>>, CsvError> {
    let err_record = self.record_index;
    let err_line = self.line;
    let err_byte = self.offset;
    // pending newline
    if self.pending_nl { self.take_pending(); }
    // skip empty lines
    loop {
        match self.peek() {
            None => return Ok(None),
            Some(b'\n') => { self.bump(); }         // advance pos, offset+1, line+1
            Some(b'\r') => { self.bump(); if self.peek()==Some(b'\n') { self.bump(); } }
            _ => break,
        }
    }
    if self.pos >= self.data.len() { return Ok(None); }
    // parse fields
    let mut fields = Vec::new();
    loop {
        let mut field = Vec::new();
        // check for quote start
        if self.peek() == Some(b'"') {
            self.bump();
            loop {
                match self.peek() {
                    None => break,   // unterminated quote: the field ends at EOF
                    Some(b'"') => {
                        self.bump();
                        if self.peek() == Some(b'"') { self.bump(); field.push(b'"'); }
                        else { break; }   // end of quoted field
                    }
                    Some(c) => { self.bump(); field.push(c); }
                }
            }
            // after the closing quote, subsequent chars until the delimiter/terminator are appended
            loop {
                match self.peek() {
                    None => break,
                    Some(c) if c == self.delimiter || c == b'\n' || c == b'\r' => break,
                    Some(c) => { self.bump(); field.push(c); }
                }
            }
        } else {
            loop {
                match self.peek() {
                    None => break,
                    Some(c) if c == self.delimiter => break,
                    Some(c) if c == b'\n' || c == b'\r' => break,
                    Some(c) => { self.bump(); field.push(c); }
                }
            }
        }
        fields.push(field);
        // after a field: delimiter -> next field; terminator -> end record; EOF -> end record
        match self.peek() {
            None => { self.record_index += 1; return Ok(Some(fields)); }
            Some(c) if c == self.delimiter => { self.bump(); continue; }
            Some(b'\n') => { self.bump(); self.record_index += 1; return Ok(Some(fields)); }
            Some(b'\r') => {
                self.bump();
                if self.peek() == Some(b'\n') { self.pending_nl = true; }
                self.record_index += 1;
                return Ok(Some(fields));
            }
            _ => unreachable!(),
        }
    }
}
