//! A minimal CSV reader that mirrors the behaviour (and error reporting) of the
//! upstream implementation.

pub const LF: u8 = b'\n';
pub const CR: u8 = b'\r';
pub const QUOTE: u8 = b'"';

#[derive(Debug, Clone)]
pub enum ErrorKind {
    /// record has a different number of fields than the previous record
    UnequalLengths { fields: usize, expected: usize },
    /// a field contained invalid utf-8
    Utf8 { field: usize, index: usize },
}

impl ErrorKind {
    pub fn message(&self) -> String {
        match self {
            ErrorKind::UnequalLengths { fields, expected } => format!(
                "found record with {} fields, but the previous record has {} fields",
                fields, expected
            ),
            ErrorKind::Utf8 { field, index } => format!(
                "invalid utf-8: invalid UTF-8 in field {} near byte index {}",
                field, index
            ),
        }
    }
    pub fn prefix(&self) -> &'static str {
        match self {
            ErrorKind::UnequalLengths { .. } => "CSV error",
            ErrorKind::Utf8 { .. } => "CSV parse error",
        }
    }
}

#[derive(Debug, Clone)]
pub struct Error {
    pub kind: ErrorKind,
    pub record: u64,
    pub line: u64,
    pub byte: u64,
}

impl Error {
    pub fn to_string(&self) -> String {
        match self.kind {
            ErrorKind::UnequalLengths { .. } => format!(
                "{}: record {} (line: {}, byte: {}): {}",
                self.kind.prefix(),
                self.record,
                self.line,
                self.byte,
                self.kind.message()
            ),
            ErrorKind::Utf8 { .. } => format!(
                "{}: record {} (line {}, field: {}, byte: {}): {}",
                self.kind.prefix(),
                self.record,
                self.line,
                self.kind.field_of(),
                self.byte,
                self.kind.message()
            ),
        }
    }
}

impl ErrorKind {
    fn field_of(&self) -> usize {
        match self {
            ErrorKind::UnequalLengths { .. } => 0,
            ErrorKind::Utf8 { field, .. } => *field,
        }
    }
}

pub struct Reader {
    data: Vec<u8>,
    pos: usize,
    /// bookkeeping offset used in error messages
    offset: u64,
    line: u64,
    /// a `\n` that terminates a `\r\n` sequence is not accounted for directly
    pending_nl: bool,
    record_index: u64,
    delimiter: u8,
    expected: Option<usize>,
}

impl Reader {
    pub fn new(data: Vec<u8>, delimiter: u8) -> Reader {
        Reader {
            data,
            pos: 0,
            offset: 0,
            line: 1,
            pending_nl: false,
            record_index: 0,
            delimiter,
            expected: None,
        }
    }

    fn peek(&self) -> Option<u8> {
        self.data.get(self.pos).copied()
    }

    /// consume the byte at the current position
    fn bump(&mut self) {
        let b = self.data[self.pos];
        self.pos += 1;
        self.offset += 1;
        if b == LF {
            self.line += 1;
        }
    }

    fn next_record(&mut self) -> Result<Option<Vec<Vec<u8>>>, Error> {
        let err_record = self.record_index;
        let err_line = self.line;
        let err_byte = self.offset;
        if self.pending_nl {
            self.pending_nl = false;
            self.bump();
        }
        // empty lines are ignored
        loop {
            match self.peek() {
                None => return Ok(None),
                Some(LF) => self.bump(),
                Some(CR) => {
                    self.bump();
                    if self.peek() == Some(LF) {
                        self.bump();
                    }
                }
                _ => break,
            }
        }
        if self.pos >= self.data.len() {
            return Ok(None);
        }
        let mut fields: Vec<Vec<u8>> = Vec::new();
        loop {
            let mut field: Vec<u8> = Vec::new();
            if self.peek() == Some(QUOTE) {
                self.bump();
                loop {
                    match self.peek() {
                        None => break,
                        Some(QUOTE) => {
                            self.bump();
                            if self.peek() == Some(QUOTE) {
                                self.bump();
                                field.push(QUOTE);
                            } else {
                                break;
                            }
                        }
                        Some(_) => {
                            let b = self.data[self.pos];
                            self.bump();
                            field.push(b);
                        }
                    }
                }
                // bytes after the closing quote are kept verbatim
                loop {
                    match self.peek() {
                        None => break,
                        Some(c)
                            if c == self.delimiter || c == LF || c == CR =>
                        {
                            break
                        }
                        Some(_) => {
                            let b = self.data[self.pos];
                            self.bump();
                            field.push(b);
                        }
                    }
                }
            } else {
                loop {
                    match self.peek() {
                        None => break,
                        Some(c) if c == self.delimiter || c == LF || c == CR => break,
                        Some(_) => {
                            let b = self.data[self.pos];
                            self.bump();
                            field.push(b);
                        }
                    }
                }
            }
            fields.push(field);
            match self.peek() {
                None => break,
                Some(c) if c == self.delimiter => {
                    self.bump();
                    continue;
                }
                Some(LF) => {
                    self.bump();
                    break;
                }
                Some(CR) => {
                    self.bump();
                    if self.peek() == Some(LF) {
                        self.pending_nl = true;
                    }
                    break;
                }
                _ => break,
            }
        }
        // number of fields must match the previous record
        if let Some(exp) = self.expected {
            if fields.len() != exp {
                self.record_index += 1;
                return Err(Error {
                    kind: ErrorKind::UnequalLengths {
                        fields: fields.len(),
                        expected: exp,
                    },
                    record: err_record,
                    line: err_line,
                    byte: err_byte,
                });
            }
        } else {
            self.expected = Some(fields.len());
        }
        // validate utf-8 field by field
        for (i, f) in fields.iter().enumerate() {
            if let Err(index) = validate_utf8(f) {
                self.record_index += 1;
                return Err(Error {
                    kind: ErrorKind::Utf8 { field: i, index },
                    record: err_record,
                    line: err_line,
                    byte: err_byte,
                });
            }
        }
        self.record_index += 1;
        Ok(Some(fields))
    }
}

/// Verify that `bytes` is valid utf-8, returning the index at which the
/// validation failed (mirroring `std::str::Utf8Error::index`).
fn validate_utf8(bytes: &[u8]) -> Result<(), usize> {
    let mut i = 0usize;
    while i < bytes.len() {
        let b = bytes[i];
        if b < 0x80 {
            i += 1;
            continue;
        }
        let (len, min) = if b >= 0xF0 {
            (4u8, 0x90u8)
        } else if b >= 0xE0 {
            (3u8, 0xA0u8)
        } else if b >= 0xC2 {
            (2u8, 0x80u8)
        } else {
            return Err(i);
        };
        if i + len as usize > bytes.len() {
            return Err(i);
        }
        let b1 = bytes[i + 1];
        if b1 & 0xC0 != 0x80 || (len == 2 && b1 < min) || (len == 3 && b1 < min) {
            return Err(i);
        }
        if len >= 3 {
            let b2 = bytes[i + 2];
            if b2 & 0xC0 != 0x80 {
                return Err(i);
            }
        }
        if len == 4 {
            let b3 = bytes[i + 3];
            if b3 & 0xC0 != 0x80 {
                return Err(i);
            }
        }
        i += len as usize;
    }
    Ok(())
}

/// Records of the input, stopping at the first error.
pub fn records(
    data: Vec<u8>,
    delimiter: u8,
) -> (Vec<Vec<String>>, Option<Error>) {
    let mut rdr = Reader::new(data, delimiter);
    let mut out = Vec::new();
    loop {
        match rdr.next_record() {
            Ok(None) => break,
            Ok(Some(fields)) => {
                let s: Vec<String> = fields
                    .iter()
                    .map(|f| String::from_utf8_lossy(f).into_owned())
                    .collect();
                out.push(s);
            }
            Err(e) => return (out, Some(e)),
        }
    }
    (out, None)
}
