                        None => break,
                        Some(QUOTE) => {
                            self.bump();
                            if self.peek() == Some(QUOTE) {
                                self.bump();
                                field.push(QUOTE);
                            } else {
                                break;
                            }
                        }
                        Some(_) => {
                            let b = self.data[self.pos];
                            self.bump();
                            field.push(b);
                        }
                    }
                }
                // bytes after the closing quote are kept verbatim
                loop {
                    match self.peek() {
                        None => break,
                        Some(c)
                            if c == self.delimiter || c == LF || c == CR =>
                        {
                            break
                        }
                        Some(_) => {
                            let b = self.data[self.pos];
                            self.bump();
                            field.push(b);
                        }
                    }
                }
            } else {
                loop {
                    match self.peek() {
                        None => break,
                        Some(c) if c == self.delimiter || c == LF || c == CR => break,
                        Some(_) => {
                            let b = self.data[self.pos];
                            self.bump();
                            field.push(b);
                        }
                    }
                }
            }
            fields.push(field);
            match self.peek() {
                None => break,
                Some(c) if c == self.delimiter => {
                    self.bump();
                    continue;
                }
                Some(LF) => {
                    self.bump();
                    break;
                }
                Some(CR) => {
                    self.bump();
                    if self.peek() == Some(LF) {
                        self.pending_nl = true;
                    }
                    break;
                }
                _ => break,
            }
        }
        // number of fields must match the previous record
        if let Some(exp) = self.expected {
            if fields.len() != exp {
                self.record_index += 1;
                return Err(Error {
                    kind: ErrorKind::UnequalLengths {
                        fields: fields.len(),
                        expected: exp,
                    },
                    record: err_record,
                    line: err_line,
                    byte: err_byte,
                });
            }
        } else {
            self.expected = Some(fields.len());
        }
        // validate utf-8 field by field
        for (i, f) in fields.iter().enumerate() {
            if let Err(index) = validate_utf8(f) {
                self.record_index += 1;
                return Err(Error {
                    kind: ErrorKind::Utf8 { field: i, index },
                    record: err_record,
                    line: err_line,
                    byte: err_byte,
                });
            }
        }
        self.record_index += 1;
        Ok(Some(fields))
    }
}

/// Verify that `bytes` is valid utf-8, returning the index at which the
/// validation failed (mirroring `std::str::Utf8Error::index`).
fn validate_utf8(bytes: &[u8]) -> Result<(), usize> {
    let mut i = 0usize;
    while i < bytes.len() {
        let b = bytes[i];
        if b < 0x80 {
            i += 1;
            continue;
        }
        let (len, min) = if b >= 0xF0 {
            (4u8, 0x90u8)
        } else if b >= 0xE0 {
            (3u8, 0xA0u8)
        } else if b >= 0xC2 {
            (2u8, 0x80u8)
        } else {
            return Err(i);
        };
        if i + len as usize > bytes.len() {
            return Err(i);
        }
        let b1 = bytes[i + 1];
        if b1 & 0xC0 != 0x80 || (len == 2 && b1 < min) || (len == 3 && b1 < min) {
            return Err(i);
        }
        if len >= 3 {
            let b2 = bytes[i + 2];
            if b2 & 0xC0 != 0x80 {
                return Err(i);
            }
        }
        if len == 4 {
            let b3 = bytes[i + 3];
            if b3 & 0xC0 != 0x80 {
                return Err(i);
            }
        }
        i += len as usize;
    }
    Ok(())
}

/// Records of the input, stopping at the first error.
pub fn records(
    data: Vec<u8>,
    delimiter: u8,
) -> (Vec<Vec<String>>, Option<Error>) {
    let mut rdr = Reader::new(data, delimiter);
    let mut out = Vec::new();
    loop {
        match rdr.next_record() {
            Ok(None) => break,
            Ok(Some(fields)) => {
                let s: Vec<String> = fields
                    .iter()
                    .map(|f| String::from_utf8_lossy(f).into_owned())
                    .collect();
                out.push(s);
            }
            Err(e) => return (out, Some(e)),
        }
    }
    (out, None)
}
