    }
    let extra = w - sw;
    match align {
        Align::Left => {
            let mut r = String::from(s);
            for _ in 0..extra {
                r.push(' ');
            }
            r
        }
        Align::Right => {
            let mut r = String::new();
            for _ in 0..extra {
                r.push(' ');
            }
            r.push_str(s);
