    }
}

pub fn render(
    t: &Table,
    style: Style,
    padding: usize,
    indent: usize,
    header_align: Align,
    body_align: Align,
) -> String {
    let b = style.borders();
    let ncols = t.ncols();
    let ind: String = " ".repeat(indent);
    let mut out = String::new();
    let cellw: Vec<usize> = t.widths.iter().map(|w| w + 2 * padding).collect();

    let mut line = |s: &str, out: &mut String| {
        if !s.is_empty() || !ind.is_empty() {
            out.push_str(&ind);
            out.push_str(s);
        }
        out.push('\n');
