            for _ in 0..padding {
                cell.push(' ');
            }
            s.push_str(&cell);
        }
        s.push(b.right);
        line(&s, out);
    };

    if b.outer {
        rule(b.tl, b.tm, b.tr, &mut out);
    }
    if !t.headers.is_empty() || !t.rows.is_empty() {
        row_line(&t.headers, header_align, &mut out);
    }
    if !t.headers.is_empty() && !t.rows.is_empty() && style.has_borders() {
        rule(b.ml, b.mm, b.mr, &mut out);
    }
    for (i, r) in t.rows.iter().enumerate() {
        row_line(r, body_align, &mut out);
        if b.all_rows && i + 1 < t.rows.len() {
            rule(b.ml, b.mm, b.mr, &mut out);
        }
    }
    if b.outer {
        rule(b.bl, b.bm, b.br, &mut out);
    }
    out
}
