/// Truncate a string so that it does not occupy more than `max` columns.
/// Zero width characters are always kept.
fn truncate(s: &str, max: usize) -> String {
    if width(s) <= max {
        return s.to_string();
    }
    let mut out = String::new();
    let mut acc = 0usize;
    for c in s.chars() {
        let w = width(&c.to_string());
        if acc + w > max {
            break;
        }
        acc += w;
        out.push(c);
    }
    out
}

fn pad(s: &str, w: usize, align: Align) -> String {
    let sw = width(s);
    if sw >= w {
        return s.to_string();
    }
    let extra = w - sw;
    match align {
        Align::Left => {
            let mut r = String::from(s);
            for _ in 0..extra {
                r.push(' ');
            }
            r
        }
        Align::Right => {
            let mut r = String::new();
            for _ in 0..extra {
                r.push(' ');
            }
            r.push_str(s);
            r
        }
        Align::Center => {
            let l = extra / 2;
            let rgt = extra - l;
            let mut r = String::new();
            for _ in 0..l {
                r.push(' ');
            }
            r.push_str(s);
            for _ in 0..rgt {
                r.push(' ');
            }
            r
        }
    }
}

pub struct Table {
    pub headers: Vec<String>,
    pub rows: Vec<Vec<String>>,
    pub widths: Vec<usize>,
}

impl Table {
    pub fn new(headers: Option<Vec<String>>, rows: Vec<Vec<String>>) -> Table {
        let ncols = rows
            .iter()
            .map(|r| r.len())
            .chain(headers.iter().map(|h| h.len()))
            .max()
            .unwrap_or(0);
        let mut headers = headers.unwrap_or_default();
        headers.resize(ncols, String::new());
        let mut rows = rows;
        for r in rows.iter_mut() {
            r.resize(ncols, String::new());
        }
        Table {
            headers,
            rows,
            widths: vec![0; ncols],
        }
    }

    pub fn ncols(&self) -> usize {
        self.widths.len()
    }

    pub fn nrows(&self) -> usize {
        self.rows.len()
    }

    pub fn line_count(&self) -> usize {
        // top border, header, separator, body rows..., bottom border
        let mut n = self.rows.len();
        if !self.headers.is_empty() || !self.rows.is_empty() {
            n += 1; // header row
        }
        n
    }
}

pub fn render(
    t: &Table,
    style: Style,
    padding: usize,
    indent: usize,
    header_align: Align,
    body_align: Align,
) -> String {
    let b = style.borders();
    let ncols = t.ncols();
    let ind: String = " ".repeat(indent);
    let mut out = String::new();
    let cellw: Vec<usize> = t.widths.iter().map(|w| w + 2 * padding).collect();

    let mut line = |s: &str, out: &mut String| {
        if !s.is_empty() || !ind.is_empty() {
            out.push_str(&ind);
            out.push_str(s);
        }
        out.push('\n');
    };

    let rule = |left: char, mid: char, right: char, out: &mut String| {
        let mut s = String::new();
        s.push(left);
        for (i, w) in cellw.iter().enumerate() {
            if i > 0 {
                s.push(mid);
            }
            for _ in 0..*w {
                s.push(b.h);
            }
        }
        s.push(right);
        line(&s, out);
    };

    let row_line = |cells: &Vec<String>, align: Align, out: &mut String| {
        let mut s = String::new();
        s.push(b.left);
        for (i, c) in cells.iter().enumerate() {
            if i > 0 {
                s.push(b.sep);
            }
            let mut cell = String::new();
            for _ in 0..padding {
                cell.push(' ');
            }
            let tc = truncate(c, t.widths[i]);
            cell.push_str(&pad(&tc, t.widths[i], align));
            for _ in 0..padding {
                cell.push(' ');
            }
            s.push_str(&cell);
        }
        s.push(b.right);
        line(&s, out);
    };

    if b.outer {
        rule(b.tl, b.tm, b.tr, &mut out);
    }
    if !t.headers.is_empty() || !t.rows.is_empty() {
        row_line(&t.headers, header_align, &mut out);
    }
    if !t.headers.is_empty() && !t.rows.is_empty() && style.has_borders() {
        rule(b.ml, b.mm, b.mr, &mut out);
    }
    for (i, r) in t.rows.iter().enumerate() {
        row_line(r, body_align, &mut out);
        if b.all_rows && i + 1 < t.rows.len() {
            rule(b.ml, b.mm, b.mr, &mut out);
        }
    }
    if b.outer {
        rule(b.bl, b.bm, b.br, &mut out);
    }
    out
}
