pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = generic_jaro(...);
    // Don't limit the length of the common prefix
    let prefix_length = a.chars().zip(b.chars()).take_while(|&(ref a_elem, ref b_elem)| a_elem == b_elem).count();
    let jaro_winkler_distance = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    if jaro_winkler_distance <= 1.0 { jaro_winkler_distance } else { 1.0 }
}
