//! Command line parsing, replicating the help/error output of the upstream
//! implementation.

use crate::table::{Align, Style};
use std::io::IsTerminal;
use std::io::Write;

pub const VERSION: &str = "csview 1.3.4";
pub const ABOUT: &str = "A high performance csv viewer with cjk/emoji support.";

#[derive(Clone, Copy, PartialEq)]
pub enum ArgId {
    NoHeaders,
    Number,
    Seq,
    Tsv,
    Delimiter,
    Style,
    Padding,
    Indent,
    Sniff,
    HeaderAlign,
    BodyAlign,
    DisablePager,
    Help,
    Version,
}

struct Spec {
    id: ArgId,
    short: Option<char>,
    long: &'static str,
    value: Option<&'static str>,
    help: &'static str,
    default: Option<&'static str>,
    possible: Option<&'static [&'static str]>,
    hidden: bool,
}

const STYLE_VALUES: &[&str] = &[
    "none",
    "ascii",
    "ascii2",
    "sharp",
    "rounded",
    "reinforced",
    "markdown",
    "grid",
];
const ALIGN_VALUES: &[&str] = &["left", "center", "right"];

fn specs() -> Vec<Spec> {
    vec![
        Spec { id: ArgId::NoHeaders, short: Some('H'), long: "no-headers", value: None,
            help: "Specify that the input has no header row", default: None, possible: None, hidden: false },
        Spec { id: ArgId::Number, short: Some('n'), long: "number", value: None,
            help: "Prepend a column of line numbers to the table", default: None, possible: None, hidden: false },
        Spec { id: ArgId::Seq, short: None, long: "seq", value: None,
            help: "", default: None, possible: None, hidden: true },
        Spec { id: ArgId::Tsv, short: Some('t'), long: "tsv", value: None,
            help: "Use '\\t' as delimiter for tsv", default: None, possible: None, hidden: false },
        Spec { id: ArgId::Delimiter, short: Some('d'), long: "delimiter", value: Some("DELIMITER"),
            help: "Specify the field delimiter", default: Some(","), possible: None, hidden: false },
        Spec { id: ArgId::Style, short: Some('s'), long: "style", value: Some("STYLE"),
            help: "Specify the border style", default: Some("sharp"), possible: Some(STYLE_VALUES), hidden: false },
        Spec { id: ArgId::Padding, short: Some('p'), long: "padding", value: Some("PADDING"),
            help: "Specify padding for table cell", default: Some("1"), possible: None, hidden: false },
        Spec { id: ArgId::Indent, short: Some('i'), long: "indent", value: Some("INDENT"),
            help: "Specify global indent for table", default: Some("0"), possible: None, hidden: false },
        Spec { id: ArgId::Sniff, short: None, long: "sniff", value: Some("LIMIT"),
            help: "Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit",
            default: Some("1000"), possible: None, hidden: false },
        Spec { id: ArgId::HeaderAlign, short: None, long: "header-align", value: Some("HEADER_ALIGN"),
            help: "Specify the alignment of the table header", default: Some("center"), possible: Some(ALIGN_VALUES), hidden: false },
        Spec { id: ArgId::BodyAlign, short: None, long: "body-align", value: Some("BODY_ALIGN"),
            help: "Specify the alignment of the table body", default: Some("left"), possible: Some(ALIGN_VALUES), hidden: false },
        Spec { id: ArgId::DisablePager, short: Some('P'), long: "disable-pager", value: None,
            help: "Disable pager", default: None, possible: None, hidden: false },
        Spec { id: ArgId::Help, short: Some('h'), long: "help", value: None,
            help: "Print help", default: None, possible: None, hidden: false },
        Spec { id: ArgId::Version, short: Some('V'), long: "version", value: None,
            help: "Print version", default: None, possible: None, hidden: false },
    ]
}

/// The visible argument list used in some usage strings.
const USAGE_ALTERNATION: &str = "<FILE|--no-headers|--number|--tsv|--delimiter <DELIMITER>|--style <STYLE>|--padding <PADDING>|--indent <INDENT>|--sniff <LIMIT>|--header-align <HEADER_ALIGN>|--body-align <BODY_ALIGN>|--disable-pager>";

pub struct Config {
    pub no_headers: bool,
    pub number: bool,
    pub tsv: bool,
    pub delimiter: char,
    pub style: Style,
    pub padding: usize,
    pub indent: usize,
    pub sniff: usize,
    pub header_align: Align,
    pub body_align: Align,
    pub disable_pager: bool,
    pub file: Option<String>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            no_headers: false,
            number: false,
            tsv: false,
            delimiter: ',',
            style: Style::Sharp,
            padding: 1,
            indent: 0,
            sniff: 1000,
            header_align: Align::Center,
            body_align: Align::Left,
            disable_pager: false,
            file: None,
        }
    }
}

pub enum Outcome {
    Run(Config),
    Help(String),
    Version(String),
    Error(String),
}

// ---------------------------------------------------------------- styling ---

const RESET: &str = "\u{1b}[0m";
fn header(s: &str) -> String {
    format!("\u{1b}[1m\u{1b}[33m{}{}", s, RESET)
}
fn literal(s: &str) -> String {
    format!("\u{1b}[1m\u{1b}[32m{}{}", s, RESET)
}
fn placeholder(s: &str) -> String {
    format!("\u{1b}[36m{}{}", s, RESET)
}
fn error_styled(s: &str) -> String {
    format!("\u{1b}[1m\u{1b}[31m{}{}", s, RESET)
}
fn invalid_styled(s: &str) -> String {
    format!("\u{1b}[33m{}{}", s, RESET)
}
fn valid_styled(s: &str) -> String {
    format!("\u{1b}[32m{}{}", s, RESET)
}

// -------------------------------------------------------------- similarity ---

/// `strsim::jaro` similarity
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let al = a.len();
    let bl = b.len();
    if al == 0 && bl == 0 {
        return 1.0;
    }
    if al == 0 || bl == 0 {
        return 0.0;
    }
    if al == 1 && bl == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }
    let sr = (std::cmp::max(al, bl) / 2).saturating_sub(1);
    let mut consumed = vec![false; bl];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, ae) in a.iter().enumerate() {
        let min_bound = if i > sr { i - sr } else { 0 };
        let max_bound = std::cmp::min(bl - 1, i + sr);
        if min_bound > max_bound {
            continue;
        }
        for (j, be) in b.iter().enumerate() {
            if min_bound <= j && j <= max_bound && ae == be && !consumed[j] {
                consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (matches / al as f64 + matches / bl as f64 + (matches - transpositions) / matches) / 3.0
    }
}

fn did_you_mean(v: &str, candidates: &[&'static str]) -> Option<&'static str> {
    let mut cands: Vec<(f64, &'static str)> = candidates
        .iter()
        .map(|c| (jaro(v, c), *c))
        .filter(|(conf, _)| *conf > 0.7)
        .collect();
    // stable sort ascending then reverse: later candidates win ties
    cands.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    cands.reverse();
    cands.first().map(|(_, c)| *c)
}

fn long_names() -> Vec<&'static str> {
    specs().iter().map(|s| s.long).collect()
}

// ----------------------------------------------------------------- wrapping ---

/// greedy word wrap
fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut lines = Vec::new();
    let mut cur = String::new();
    for word in text.split(' ') {
        if cur.is_empty() {
            cur.push_str(word);
        } else if cur.chars().count() + 1 + word.chars().count() <= width {
            cur.push(' ');
            cur.push_str(word);
        } else {
            lines.push(std::mem::take(&mut cur));
            cur.push_str(word);
        }
    }
    lines.push(cur);
    lines
}

// -------------------------------------------------------------------- help ---

fn opt_usage(sp: &Spec, color: bool) -> String {
    let mut s = String::new();
    let lit = |x: &str| if color { literal(x) } else { x.to_string() };
    let ph = |x: &str| if color { placeholder(x) } else { x.to_string() };
    match sp.short {
        Some(c) => {
            s.push_str(&lit(&format!("-{}", c)));
            s.push_str(", ");
        }
        None => s.push_str("      "),
    }
    s.push_str(&lit(&format!("--{}", sp.long)));
    if let Some(v) = sp.value {
        s.push_str(&ph(" "));
        s.push_str(&ph(&format!("<{}>", v)));
    }
    s
}

pub fn help_text(name: &str, width: usize, color: bool) -> String {
    let mut out = String::new();
    let wrapw = if width >= 10 { width - 10 } else { 0 };
    let mut push_wrapped = |text: &str, indent: usize, w: usize, out: &mut String| {
        let pad = " ".repeat(indent);
        for l in wrap(text, w) {
            out.push_str(&pad);
            out.push_str(&l);
            out.push('\n');
        }
    };
    push_wrapped(ABOUT, 0, width, &mut out);
    out.push('\n');
    // usage
    if color {
        out.push_str(&header("Usage:"));
        out.push(' ');
        out.push_str(&literal(name));
        out.push(' ');
        out.push_str(&placeholder("[OPTIONS]"));
        out.push(' ');
        out.push_str(&placeholder("[FILE]"));
    } else {
        out.push_str(&format!("Usage: {} [OPTIONS] [FILE]", name));
    }
    out.push('\n');
    out.push('\n');
    if color {
        out.push_str(&header("Arguments:"));
    } else {
        out.push_str("Arguments:");
    }
    out.push('\n');
    out.push_str("  ");
    if color {
        out.push_str(&placeholder("[FILE]"));
    } else {
        out.push_str("[FILE]");
    }
    out.push('\n');
    push_wrapped("File to view", 10, wrapw, &mut out);
    out.push('\n');
    if color {
        out.push_str(&header("Options:"));
    } else {
        out.push_str("Options:");
    }
    out.push('\n');
    for sp in specs().iter() {
        if sp.hidden {
            continue;
        }
        out.push_str("  ");
        out.push_str(&opt_usage(sp, color));
        out.push('\n');
        let mut help = sp.help.to_string();
        if let Some(d) = sp.default {
            help.push_str(&format!(" [default: {}]", d));
        }
        if let Some(p) = sp.possible {
            help.push_str(&format!(" [possible values: {}]", p.join(", ")));
        }
        push_wrapped(&help, 10, wrapw, &mut out);
    }
    out
}

// ------------------------------------------------------------------ errors ---

fn err_header() -> String {
    error_styled("error:")
}

fn footer(out: &mut String, color: bool) {
    if color {
        out.push_str(&format!(
            "\nFor more information, try '{}'.\n",
            literal("--help")
        ));
    } else {
        out.push_str("\nFor more information, try '--help'.\n");
    }
}

fn usage_line(name: &str, color: bool, form: UsageForm, used: &[ArgId]) -> String {
    match form {
        UsageForm::Default => {
            if color {
                format!(
                    "{} {} {} {}",
                    header("Usage:"),
                    literal(name),
                    placeholder("[OPTIONS]"),
                    placeholder("[FILE]")
                )
            } else {
                format!("Usage: {} [OPTIONS] [FILE]", name)
            }
        }
        UsageForm::Alternation => {
            if color {
                format!("{} {} {}", header("Usage:"), literal(name), placeholder(USAGE_ALTERNATION))
            } else {
                format!("Usage: {} {}", name, USAGE_ALTERNATION)
            }
        }
        UsageForm::Args(body) => {
            if color {
                let mut s = format!("{} {}", header("Usage:"), literal(name));
                for u in body {
                    s.push(' ');
                    s.push_str(&u);
                }
                s
            } else {
                format!("Usage: {} {}", name, body.join(" "))
            }
        }
    }
}

#[derive(Clone, Copy, PartialEq)]
enum UsageForm {
    Default,
    Alternation,
    Args,
}

fn spec_by_id(id: ArgId) -> &'static Spec {
    specs().iter().find(|s| s.id == id).unwrap()
}

fn arg_usage(id: ArgId, color: bool) -> String {
    let sp = spec_by_id(id);
    match sp.value {
        Some(v) => {
            if color {
                format!("{}{}{}", literal(&format!("--{}", sp.long)), placeholder(" "), placeholder(&format!("<{}>", v)))
            } else {
                format!("--{} <{}>", sp.long, v)
            }
        }
        None => {
            if color {
                literal(&format!("--{}", sp.long))
            } else {
                format!("--{}", sp.long)
            }
        }
    }
}

pub struct ErrCtx {
    pub name: String,
    pub color: bool,
    /// arguments already present, in the order they were set
    pub used: Vec<ArgId>,
}

impl ErrCtx {
    fn form_for_unknown(&self, suggestion: bool, positional_only: bool) -> UsageForm {
        if positional_only {
            return UsageForm::Default;
        }
        if suggestion || !self.used.is_empty() {
            UsageForm::Alternation
        } else {
            UsageForm::Default
        }
    }
    fn form_for_too_many_values(&self) -> UsageForm {
        // a flag or an attached value makes the used args visible
        if !self.used.is_empty() {
            UsageForm::Alternation
        } else {
            UsageForm::Args
        }
    }
}

fn unexpected_argument(ctx: &ErrCtx, arg: &str, suggestion: Option<&str>, positional_only: bool) -> String {
    let mut out = String::new();
    if ctx.color {
        out.push_str(&format!(
            "{} unexpected argument '{}' found\n",
            err_header(),
            invalid_styled(arg)
        ));
    } else {
        out.push_str(&format!("error: unexpected argument '{}' found\n", arg));
    }
    if let Some(s) = suggestion {
        if ctx.color {
            out.push_str(&format!(
                "\n  {} a similar argument exists: '{}'\n",
                valid_styled("tip:"),
                valid_styled(s)
            ));
        } else {
            out.push_str(&format!("\n  tip: a similar argument exists: '{}'\n", s));
        }
    } else {
        if ctx.color {
            out.push_str(&format!(
                "\n  {} to pass '{}' as a value, use '{}'\n",
                valid_styled("tip:"),
                invalid_styled(arg),
                valid_styled(&format!("-- {}", arg))
            ));
        } else {
            out.push_str(&format!(
                "\n  tip: to pass '{}' as a value, use '-- {}'\n",
                arg
            ));
        }
    }
    let form = ctx.form_for_unknown(suggestion.is_some(), positional_only);
    out.push('\n');
    out.push_str(&usage_line(&ctx.name, ctx.color, form, &ctx.used));
    out.push('\n');
    footer(&mut out, ctx.color);
    out
}

fn extra_positional(ctx: &ErrCtx, arg: &str) -> String {
    let mut out = String::new();
    if ctx.color {
        out.push_str(&format!(
            "{} unexpected argument '{}' found\n",
            err_header(),
            invalid_styled(arg)
        ));
    } else {
        out.push_str(&format!("error: unexpected argument '{}' found\n", arg));
    }
    out.push('\n');
    out.push_str(&usage_line(&ctx.name, ctx.color, UsageForm::Default, &ctx.used));
    out.push('\n');
    footer(&mut out, ctx.color);
    out
}

fn too_many_values(ctx: &ErrCtx, val: &str, arg: ArgId) -> String {
    let mut out = String::new();
    let sp = spec_by_id(arg);
    let long = format!("--{}", sp.long);
    if ctx.color {
        out.push_str(&format!(
            "{} unexpected value '{}' for '{}' found; no more were expected\n",
            err_header(),
            invalid_styled(val),
            literal(&long)
        ));
    } else {
        out.push_str(&format!(
            "error: unexpected value '{}' for '{}' found; no more were expected\n",
            val, long
        ));
    }
    out.push('\n');
    let form = ctx.form_for_too_many_values();
    match form {
        UsageForm::Args => {
            if ctx.color {
                out.push_str(&format!(
                    "{} {} {} {}",
                    header("Usage:"),
                    literal(&ctx.name),
                    literal(&long),
                    placeholder("[FILE]")
                ));
            } else {
                out.push_str(&format!("Usage: {} {} [FILE]", ctx.name, long));
            }
        }
        _ => out.push_str(&usage_line(&ctx.name, ctx.color, form, &ctx.used)),
    }
    out.push('\n');
    footer(&mut out, ctx.color);
    out
}

fn missing_value(ctx: &ErrCtx, arg: ArgId) -> String {
    let sp = spec_by_id(arg);
    let shown = match sp.value {
        Some(v) => format!("--{} <{}>", sp.long, v),
        None => format!("--{}", sp.long),
    };
    let mut out = String::new();
    if ctx.color {
        out.push_str(&format!(
            "{} a value is required for '{}' but none was supplied\n",
            err_header(),
            invalid_styled(&shown)
        ));
    } else {
        out.push_str(&format!(
            "error: a value is required for '{}' but none was supplied\n",
            shown
        ));
    }
    if let Some(p) = sp.possible {
        if ctx.color {
            let list: Vec<String> = p.iter().map(|v| valid_styled(v)).collect();
            out.push_str(&format!("  [possible values: {}]\n", list.join(", ")));
        } else {
            out.push_str(&format!("  [possible values: {}]\n", p.join(", ")));
        }
    }
    footer(&mut out, ctx.color);
    out
}

fn invalid_value(ctx: &ErrCtx, val: &str, arg: ArgId, reason: Option<&str>) -> String {
    let sp = spec_by_id(arg);
    let shown = match sp.value {
        Some(v) => format!("--{} <{}>", sp.long, v),
        None => format!("--{}", sp.long),
    };
    let mut out = String::new();
    if ctx.color {
        out.push_str(&format!(
            "{} invalid value '{}' for '{}'",
            err_header(),
            invalid_styled(val),
            literal(&shown)
        ));
    } else {
        out.push_str(&format!("error: invalid value '{}' for '{}'", val, shown));
    }
    match reason {
        Some(r) => out.push_str(&format!(": {}", r)),
        None => {}
    }
    out.push('\n');
    if let Some(p) = sp.possible {
        if reason.is_none() {
            if ctx.color {
                let list: Vec<String> = p.iter().map(|v| valid_styled(v)).collect();
                out.push_str(&format!("  [possible values: {}]\n", list.join(", ")));
            } else {
                out.push_str(&format!("  [possible values: {}]\n", p.join(", ")));
            }
            let names: Vec<&str> = p.to_vec();
            if let Some(s) = did_you_mean(val, &names) {
                if ctx.color {
                    out.push_str(&format!(
                        "\n  {} a similar value exists: '{}'\n",
                        valid_styled("tip:"),
                        valid_styled(s)
                    ));
                } else {
                    out.push_str(&format!("\n  tip: a similar value exists: '{}'\n", s));
                }
            }
        }
    }
    footer(&mut out, ctx.color);
    out
}

fn conflict(ctx: &ErrCtx, a: ArgId, b: ArgId) -> String {
    // a was set first, b conflicts
    let sa = arg_usage(a, ctx.color);
    let sb_plain = {
        let sp = spec_by_id(b);
        match sp.value {
            Some(v) => format!("--{} <{}>", sp.long, v),
            None => format!("--{}", sp.long),
        }
    };
    let mut out = String::new();
    if ctx.color {
        out.push_str(&format!(
            "{} the argument '{}' cannot be used with '{}'\n",
            err_header(),
            invalid_styled(&{
                let sp = spec_by_id(a);
                match sp.value {
                    Some(v) => format!("--{} <{}>", sp.long, v),
                    None => format!("--{}", sp.long),
                }
            }),
            invalid_styled(&sb_plain)
        ));
    } else {
        out.push_str(&format!(
            "error: the argument '{}' cannot be used with '{}'\n",
            {
                let sp = spec_by_id(a);
                match sp.value {
                    Some(v) => format!("--{} <{}>", sp.long, v),
                    None => format!("--{}", sp.long),
                }
            },
            sb_plain
        ));
    }
    out.push('\n');
    let mut body: Vec<String> = Vec::new();
    for u in ctx.used.iter() {
        if *u == b {
            continue;
        }
        let sp = spec_by_id(*u);
        if ctx.color {
            match sp.value {
                Some(v) => body.push(format!(
                    "{}{}{}",
                    literal(&format!("--{}", sp.long)),
                    placeholder(" "),
                    placeholder(&format!("<{}>", v))
                )),
                None => body.push(literal(&format!("--{}", sp.long))),
            }
        } else {
            match sp.value {
                Some(v) => body.push(format!("--{} <{}>", sp.long, v)),
                None => body.push(format!("--{}", sp.long)),
            }
        }
    }
    if ctx.color {
        body.push(placeholder("<FILE>"));
    } else {
        body.push("<FILE>".to_string());
    }
    out.push_str(&usage_line(&ctx.name, ctx.color, UsageForm::Args, &ctx.used).replace(
        &usage_line(&ctx.name, ctx.color, UsageForm::Args, &ctx.used),
        &usage_line(&ctx.name, ctx.color, UsageForm::Args, &ctx.used),
    ));
    out
}

fn multiple_use(ctx: &ErrCtx, arg: ArgId) -> String {
    let sp = spec_by_id(arg);
    let shown = match sp.value {
        Some(v) => format!("--{} <{}>", sp.long, v),
        None => format!("--{}", sp.long),
    };
    let mut out = String::new();
    if ctx.color {
        out.push_str(&format!(
            "{} the argument '{}' cannot be used multiple times\n",
            err_header(),
            invalid_styled(&shown)
        ));
    } else {
        out.push_str(&format!(
            "error: the argument '{}' cannot be used multiple times\n",
            shown
        ));
    }
    out.push('\n');
    out.push_str(&usage_line(&ctx.name, ctx.color, UsageForm::Default, &ctx.used));
    out.push('\n');
    footer(&mut out, ctx.color);
    out
}

// ---------------------------------------------------------------- parsing ---

struct Raw {
    no_headers: Option<()>,
    number: Option<()>,
    tsv: Option<()>,
    delimiter: Option<String>,
    style: Option<String>,
    padding: Option<String>,
    indent: Option<String>,
    sniff: Option<String>,
    header_align: Option<String>,
    body_align: Option<String>,
    disable_pager: Option<()>,
    file: Option<String>,
    /// order in which the arguments were set
    used: Vec<ArgId>,
}

impl Raw {
    fn new() -> Raw {
        Raw {
            no_headers: None,
            number: None,
            tsv: None,
            delimiter: None,
            style: None,
            padding: None,
            indent: None,
            sniff: None,
            header_align: None,
            body_align: None,
            disable_pager: None,
            file: None,
            used: Vec::new(),
        }
    }
    fn contains(&self, id: ArgId) -> bool {
        self.used.contains(&id)
    }
}

fn parse_usize(s: &str) -> Result<usize, &'static str> {
    if s.is_empty() {
        return Err("cannot parse integer from empty string");
    }
    let bytes = s.as_bytes();
    let mut i = 0;
    if bytes[0] == b'+' {
        i = 1;
        if bytes.len() == 1 {
            return Err("cannot parse integer from empty string");
        }
    }
    for b in &bytes[i..] {
        if !b.is_ascii_digit() {
            return Err("invalid digit found in string");
        }
    }
    let digits = &s[i..];
    match digits.parse::<u128>() {
        Ok(v) => {
            if v > usize::MAX as u128 {
                Err("number too large to fit in target type")
            } else {
                Ok(v as usize)
            }
        }
        Err(_) => Err("number too large to fit in target type"),
    }
}

fn parse_align(s: &str) -> Option<Align> {
    match s {
        "left" => Some(Align::Left),
        "center" => Some(Align::Center),
        "right" => Some(Align::Right),
        _ => None,
    }
}

fn is_known_option(tok: &str) -> bool {
    if tok == "--" {
        return true;
    }
    if let Some(rest) = tok.strip_prefix("--") {
        let name = rest.split('=').next().unwrap_or("");
        return specs().iter().any(|s| s.long == name);
    }
    if let Some(rest) = tok.strip_prefix('-') {
        if let Some(c) = rest.chars().next() {
            return specs().iter().any(|s| s.short == Some(c));
        }
    }
    false
}

pub fn parse(name: &str, argv: &[String], stdout_tty: bool, stderr_tty: bool) -> Outcome {
    let ctx = ErrCtx {
        name: name.to_string(),
        color: stderr_tty,
        used: Vec::new(),
    };
    let width = term_width(stdout_tty, stderr_tty);
    let mut raw = Raw::new();
    // pending (arg, values)
    let mut pending: Option<(ArgId, Vec<String>)> = None;
    let mut trailing = false;
    let mut i = 0usize;
    let mut help_requested = false;
    let mut version_requested = false;

    macro_rules! err {
        ($e:expr) => {
            return Outcome::Error($e)
        };
    }

    // react: convert and store the pending values
    macro_rules! react {
        ($id:expr, $vals:expr) => {{
            let id: ArgId = $id;
            let vals: Vec<String> = $vals;
            if raw.contains(id) {
                err!(multiple_use(&ErrCtx { name: name.to_string(), color: stderr_tty, used: raw.used.clone() }, id));
            }
            match id {
                ArgId::Delimiter => {
                    let mut it = vals[0].chars();
                    match (it.next(), it.next()) {
                        (Some(c), None) => raw.delimiter = Some(c.to_string()),
                        (None, _) => err!(invalid_value(&ErrCtx { name: name.to_string(), color: stderr_tty, used: raw.used.clone() }, "", ArgId::Delimiter, Some("cannot parse char from empty string"))),
                        _ => err!(invalid_value(&ErrCtx { name: name.to_string(), color: stderr_tty, used: raw.used.clone() }, &vals[0], ArgId::Delimiter, Some("too many characters in string"))),
                    }
                }
                ArgId::Style => match Style::from_str(&vals[0]) {
                    Some(_) => raw.style = Some(vals[0].clone()),
                    None => err!(invalid_value(&ErrCtx { name: name.to_string(), color: stderr_tty, used: raw.used.clone() }, &vals[0], ArgId::Style, None)),
                },
                ArgId::HeaderAlign | ArgId::BodyAlign => match parse_align(&vals[0]) {
                    Some(_) => {
                        if id == ArgId::HeaderAlign {
                            raw.header_align = Some(vals[0].clone())
                        } else {
                            raw.body_align = Some(vals[0].clone())
                        }
                    }
                    None => err!(invalid_value(&ErrCtx { name: name.to_string(), color: stderr_tty, used: raw.used.clone() }, &vals[0], id, None)),
                },
                ArgId::Padding => match parse_usize(&vals[0]) {
                    Ok(_) => raw.padding = Some(vals[0].clone()),
                    Err(e) => err!(invalid_value(&ErrCtx { name: name.to_string(), color: stderr_tty, used: raw.used.clone() }, &vals[0], ArgId::Padding, Some(e))),
                },
                ArgId::Indent => match parse_usize(&vals[0]) {
                    Ok(_) => raw.indent = Some(vals[0].clone()),
                    Err(e) => err!(invalid_value(&ErrCtx { name: name.to_string(), color: stderr_tty, used: raw.used.clone() }, &vals[0], ArgId::Indent, Some(e))),
                },
                ArgId::Sniff => match parse_usize(&vals[0]) {
                    Ok(_) => raw.sniff = Some(vals[0].clone()),
                    Err(e) => err!(invalid_value(&ErrCtx { name: name.to_string(), color: stderr_tty, used: raw.used.clone() }, &vals[0], ArgId::Sniff, Some(e))),
                },
                _ => {}
            }
            raw.used.push(id);
        }};
    }

    while i < argv.len() {
        let a = argv[i].clone();
        if trailing {
            if raw.file.is_some() {
                err!(extra_positional(&ctx_for(&raw, name, stderr_tty), &a));
            }
            raw.file = Some(a);
            i += 1;
            continue;
        }
        if a == "--" {
            trailing = true;
            i += 1;
            continue;
        }
        if a.starts_with("--") {
            let body = &a[2..];
            let (lname, val) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            let found = specs().iter().find(|s| s.long == lname).map(|s| s.id);
            match found {
                Some(id) => {
                    // flush pending
                    if let Some((pid, vals)) = pending.take() {
                        react!(pid, vals);
                    }
                    let takes_value = spec_by_id(id).value.is_some();
                    if takes_value {
                        match val {
                            Some(v) => {
                                pending = Some((id, vec![v]));
                            }
                            None => {
                                // need a value from the next argument
                                if i + 1 < argv.len() {
                                    let nx = &argv[i + 1];
                                    if nx == "--" || is_known_option(nx) {
                                        err!(missing_value(&ctx_for(&raw, name, stderr_tty), id));
                                    } else if nx.starts_with('-') && nx.len() > 1 {
                                        err!(unknown_arg(&raw, name, stderr_tty, nx, false));
                                    } else {
                                        pending = Some((id, vec![nx.clone()]));
                                        i += 1;
                                    }
                                } else {
                                    err!(missing_value(&ctx_for(&raw, name, stderr_tty), id));
                                }
                            }
                        }
                    } else {
                        if let Some(v) = val {
                            err!(too_many_values(&ctx_for(&raw, name, stderr_tty), &v, id));
                        }
                        if raw.contains(id) {
                            err!(multiple_use(&ctx_for(&raw, name, stderr_tty), id));
                        }
                        raw.used.push(id);
                        match id {
                            ArgId::NoHeaders => raw.no_headers = Some(()),
                            ArgId::Number | ArgId::Seq => raw.number = Some(()),
                            ArgId::Tsv => raw.tsv = Some(()),
                            ArgId::DisablePager => raw.disable_pager = Some(()),
                            ArgId::Help => help_requested = true,
                            ArgId::Version => version_requested = true,
                            _ => {}
                        }
                    }
                }
                None => {
                    err!(unknown_arg(&raw, name, stderr_tty, &format!("--{}", lname), true));
                }
            }
            i += 1;
            continue;
        }
        if a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a.chars().collect();
            let mut j = 1usize;
            let mut consumed_next = false;
            while j < chars.len() {
                let c = chars[j];
                let found = specs().iter().find(|s| s.short == Some(c)).map(|s| s.id);
                match found {
                    Some(id) => {
                        if let Some((pid, vals)) = pending.take() {
                            react!(pid, vals);
                        }
                        let takes_value = spec_by_id(id).value.is_some();
                        if takes_value {
                            let rest: String = chars[j + 1..].iter().collect();
                            if !rest.is_empty() {
                                let v = if let Some(r) = rest.strip_prefix('=') {
                                    r.to_string()
                                } else {
                                    rest
                                };
                                pending = Some((id, vec![v]));
                            } else {
                                if i + 1 < argv.len() {
                                    let nx = &argv[i + 1];
                                    if nx == "--" || is_known_option(nx) {
                                        err!(missing_value(&ctx_for(&raw, name, stderr_tty), id));
                                    } else if nx.starts_with('-') && nx.len() > 1 {
                                        err!(unknown_arg(&raw, name, stderr_tty, nx, false));
                                    } else {
                                        pending = Some((id, vec![nx.clone()]));
                                        consumed_next = true;
                                    }
                                } else {
                                    err!(missing_value(&ctx_for(&raw, name, stderr_tty), id));
                                }
                            }
                            break;
                        } else {
                            if raw.contains(id) {
                                err!(multiple_use(&ctx_for(&raw, name, stderr_tty), id));
                            }
                            raw.used.push(id);
                            match id {
                                ArgId::NoHeaders => raw.no_headers = Some(()),
                                ArgId::Number | ArgId::Seq => raw.number = Some(()),
                                ArgId::Tsv => raw.tsv = Some(()),
                                ArgId::DisablePager => raw.disable_pager = Some(()),
                                ArgId::Help => help_requested = true,
                                ArgId::Version => version_requested = true,
                                _ => {}
                            }
                            j += 1;
                        }
                    }
                    None => {
                        err!(unknown_arg(&raw, name, stderr_tty, &format!("-{}", c), false));
                    }
                }
            }
            if consumed_next {
                i += 2;
            } else {
                i += 1;
            }
            continue;
        }
        // value or positional
        if let Some((pid, vals)) = pending.as_mut() {
            if vals.is_empty() {
                vals.push(a);
                i += 1;
                continue;
            }
        }
        if raw.file.is_some() {
            err!(extra_positional(&ctx_for(&raw, name, stderr_tty), &a));
        }
        raw.file = Some(a);
        i += 1;
    }
    if let Some((pid, vals)) = pending.take() {
        react!(pid, vals);
    }

    if help_requested {
        return Outcome::Help(help_text(name, width, stdout_tty));
    }
    if version_requested {
        return Outcome::Version(format!("{}\n", VERSION));
    }

    // conflicts
    if raw.tsv.is_some() && raw.delimiter.is_some() {
        let first = raw
            .used
            .iter()
            .find(|u| **u == ArgId::Tsv || **u == ArgId::Delimiter)
            .copied()
            .unwrap();
        let second = if first == ArgId::Tsv { ArgId::Delimiter } else { ArgId::Tsv };
        return Outcome::Error(conflict(&ctx_for(&raw, name, stderr_tty), first, second));
    }

    let mut cfg = Config::default();
    cfg.no_headers = raw.no_headers.is_some();
    cfg.number = raw.number.is_some();
    cfg.tsv = raw.tsv.is_some();
    if let Some(d) = raw.delimiter {
        cfg.delimiter = d.chars().next().unwrap();
    }
    if let Some(s) = raw.style {
        cfg.style = Style::from_str(&s).unwrap();
    }
    if let Some(p) = raw.padding {
        cfg.padding = parse_usize(&p).unwrap();
    }
    if let Some(v) = raw.indent {
        cfg.indent = parse_usize(&v).unwrap();
    }
    if let Some(s) = raw.sniff {
        cfg.sniff = parse_usize(&s).unwrap();
    }
    if let Some(h) = raw.header_align {
        cfg.header_align = parse_align(&h).unwrap();
    }
    if let Some(b) = raw.body_align {
        cfg.body_align = parse_align(&b).unwrap();
    }
    cfg.disable_pager = raw.disable_pager.is_some();
    cfg.file = raw.file;
    Outcome::Run(cfg)
}

fn ctx_for(raw: &Raw, name: &str, color: bool) -> ErrCtx {
    ErrCtx {
        name: name.to_string(),
        color,
        used: raw.used.clone(),
    }
}

fn unknown_arg(raw: &Raw, name: &str, color: bool, arg: &str, is_long: bool) -> String {
    let ctx = ctx_for(raw, name, color);
    let suggestion = if is_long {
        let stripped = arg.trim_start_matches('-');
        did_you_mean(stripped, &long_names())
    } else {
        None
    };
    unexpected_argument(&ctx, arg, suggestion, false)
}

pub fn term_width(stdout_tty: bool, stderr_tty: bool) -> usize {
    use std::os::unix::io::AsRawFd;
    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
    }
    const TIOCGWINSZ: u64 = 0x5413;
    #[repr(C)]
    struct WinSize {
        rows: u16,
        cols: u16,
        x: u16,
        y: u16,
    }
    let mut size = WinSize { rows: 0, cols: 0, x: 0, y: 0 };
    let fds = [1i32, 2, 0];
    for fd in fds.iter() {
        unsafe {
            if ioctl(*fd, TIOCGWINSZ, &mut size as *mut WinSize) == 0 && size.cols > 0 {
                return size.cols as usize;
            }
        }
    }
    if let Ok(v) = std::env::var("COLUMNS") {
        if let Ok(n) = v.parse::<usize>() {
            return n;
        }
    }
    100
}
