//! Command line parsing, replicating the help/error output of the upstream
//! implementation.

use crate::table::{Align, Style};

pub const VERSION: &str = "csview 1.3.4";
pub const ABOUT: &str = "A high performance csv viewer with cjk/emoji support.";

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum ArgId {
    NoHeaders,
    Number,
    Seq,
    Tsv,
    Delimiter,
    Style,
    Padding,
    Indent,
    Sniff,
    HeaderAlign,
    BodyAlign,
    DisablePager,
    Help,
    Version,
}

struct Spec {
    id: ArgId,
    short: Option<char>,
    long: &'static str,
    value: Option<&'static str>,
    help: &'static str,
    default: Option<&'static str>,
    possible: Option<&'static [&'static str]>,
    hidden: bool,
}

const STYLE_VALUES: &[&str] = &[
    "none",
    "ascii",
    "ascii2",
    "sharp",
    "rounded",
    "reinforced",
    "markdown",
    "grid",
];
const ALIGN_VALUES: &[&str] = &["left", "center", "right"];

