        Spec { id: ArgId::Delimiter, short: Some('d'), long: "delimiter", value: Some("DELIMITER"),
            help: "Specify the field delimiter", default: Some(","), possible: None, hidden: false },
        Spec { id: ArgId::Style, short: Some('s'), long: "style", value: Some("STYLE"),
            help: "Specify the border style", default: Some("sharp"), possible: Some(STYLE_VALUES), hidden: false },
        Spec { id: ArgId::Padding, short: Some('p'), long: "padding", value: Some("PADDING"),
            help: "Specify padding for table cell", default: Some("1"), possible: None, hidden: false },
        Spec { id: ArgId::Indent, short: Some('i'), long: "indent", value: Some("INDENT"),
            help: "Specify global indent for table", default: Some("0"), possible: None, hidden: false },
        Spec { id: ArgId::Sniff, short: None, long: "sniff", value: Some("LIMIT"),
            help: "Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit",
            default: Some("1000"), possible: None, hidden: false },
        Spec { id: ArgId::HeaderAlign, short: None, long: "header-align", value: Some("HEADER_ALIGN"),
            help: "Specify the alignment of the table header", default: Some("center"), possible: Some(ALIGN_VALUES), hidden: false },
        Spec { id: ArgId::BodyAlign, short: None, long: "body-align", value: Some("BODY_ALIGN"),
            help: "Specify the alignment of the table body", default: Some("left"), possible: Some(ALIGN_VALUES), hidden: false },
        Spec { id: ArgId::DisablePager, short: Some('P'), long: "disable-pager", value: None,
            help: "Disable pager", default: None, possible: None, hidden: false },
        Spec { id: ArgId::Help, short: Some('h'), long: "help", value: None,
            help: "Print help", default: None, possible: None, hidden: false },
        Spec { id: ArgId::Version, short: Some('V'), long: "version", value: None,
            help: "Print version", default: None, possible: None, hidden: false },
    ]
}

const USAGE_ALTERNATION: &str = "<FILE|--no-headers|--number|--tsv|--delimiter <DELIMITER>|--style <STYLE>|--padding <PADDING>|--indent <INDENT>|--sniff <LIMIT>|--header-align <HEADER_ALIGN>|--body-align <BODY_ALIGN>|--disable-pager>";

pub struct Config {
    pub no_headers: bool,
    pub number: bool,
    pub tsv: bool,
    pub delimiter: char,
    pub style: Style,
    pub padding: usize,
    pub indent: usize,
    pub sniff: usize,
    pub header_align: Align,
    pub body_align: Align,
    pub disable_pager: bool,
    pub file: Option<String>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            no_headers: false,
            number: false,
            tsv: false,
            delimiter: ',',
            style: Style::Sharp,
            padding: 1,
            indent: 0,
            sniff: 1000,
            header_align: Align::Center,
            body_align: Align::Left,
            disable_pager: false,
            file: None,
        }
    }
}

pub enum Outcome {
    Run(Box<Config>),
    Help(String),
    Version(String),
    Error(String),
}

// ---------------------------------------------------------------- styling ---

const RESET: &str = "\u{1b}[0m";
fn header(s: &str) -> String {
    format!("\u{1b}[1m\u{1b}[33m{}{}", s, RESET)
}
fn literal(s: &str) -> String {
    format!("\u{1b}[1m\u{1b}[32m{}{}", s, RESET)
}
fn placeholder(s: &str) -> String {
    format!("\u{1b}[36m{}{}", s, RESET)
}
fn err_styled(s: &str) -> String {
    format!("\u{1b}[1m\u{1b}[31m{}{}", s, RESET)
}
fn invalid_styled(s: &str) -> String {
    format!("\u{1b}[33m{}{}", s, RESET)
}
fn valid_styled(s: &str) -> String {
    format!("\u{1b}[32m{}{}", s, RESET)
}

// -------------------------------------------------------------- similarity ---

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let al = a.len();
    let bl = b.len();
    if al == 0 && bl == 0 {
        return 1.0;
    }
    if al == 0 || bl == 0 {
        return 0.0;
    }
    if al == 1 && bl == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }
    let sr = (std::cmp::max(al, bl) / 2).saturating_sub(1);
    let mut consumed = vec![false; bl];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, ae) in a.iter().enumerate() {
        let min_bound = if i > sr { i - sr } else { 0 };
        let max_bound = std::cmp::min(bl - 1, i + sr);
        if min_bound > max_bound {
            continue;
        }
        for (j, be) in b.iter().enumerate() {
            if min_bound <= j && j <= max_bound && ae == be && !consumed[j] {
                consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (matches / al as f64 + matches / bl as f64 + (matches - transpositions) / matches) / 3.0
    }
}

fn did_you_mean(v: &str, candidates: &[&'static str]) -> Option<&'static str> {
    let mut cands: Vec<(f64, &'static str)> = candidates
        .iter()
        .map(|c| (jaro(v, c), *c))
        .filter(|(conf, _)| *conf > 0.7)
        .collect();
    cands.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    cands.reverse();
    cands.first().map(|(_, c)| *c)
}

fn long_names() -> Vec<&'static str> {
    specs().iter().map(|s| s.long).collect()
}

// ----------------------------------------------------------------- wrapping ---

fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut lines = Vec::new();
    let mut cur = String::new();
    for word in text.split(' ') {
        if cur.is_empty() {
            cur.push_str(word);
        } else if cur.chars().count() + 1 + word.chars().count() <= width {
            cur.push(' ');
            cur.push_str(word);
        } else {
            lines.push(std::mem::take(&mut cur));
            cur.push_str(word);
        }
    }
    lines.push(cur);
    lines
}

// -------------------------------------------------------------------- help ---

fn opt_usage(sp: &Spec, color: bool) -> String {
    let mut s = String::new();
    match sp.short {
        Some(c) => {
            s.push_str(&styled(color, &format!("-{}", c), literal));
            s.push_str(", ");
        }
        None => s.push_str("      "),
    }
    s.push_str(&styled(color, &format!("--{}", sp.long), literal));
    if let Some(v) = sp.value {
        s.push_str(&styled(color, " ", placeholder));
        s.push_str(&styled(color, &format!("<{}>", v), placeholder));
    }
    s
}

fn styled(color: bool, s: &str, f: fn(&str) -> String) -> String {
    if color {
        f(s)
    } else {
        s.to_string()
    }
}

pub fn help_text(name: &str, width: usize, color: bool) -> String {
    let mut out = String::new();
    let wrapw = if width >= 10 { width - 10 } else { 0 };
    let mut push_wrapped = |text: &str, indent: usize, w: usize, out: &mut String| {
        let pad = " ".repeat(indent);
        for l in wrap(text, w) {
            out.push_str(&pad);
            out.push_str(&l);
            out.push('\n');
        }
    };
    push_wrapped(ABOUT, 0, width, &mut out);
    out.push('\n');
    if color {
        out.push_str(&header("Usage:"));
        out.push(' ');
        out.push_str(&literal(name));
        out.push(' ');
        out.push_str(&placeholder("[OPTIONS]"));
        out.push(' ');
        out.push_str(&placeholder("[FILE]"));
    } else {
        out.push_str(&format!("Usage: {} [OPTIONS] [FILE]", name));
    }
    out.push_str("\n\n");
    out.push_str(&styled(color, "Arguments:", header));
    out.push('\n');
    out.push_str("  ");
    out.push_str(&styled(color, "[FILE]", placeholder));
    out.push('\n');
    push_wrapped("File to view", 10, wrapw, &mut out);
    out.push('\n');
    out.push_str(&styled(color, "Options:", header));
    out.push('\n');
    for sp in specs().iter() {
        if sp.hidden {
            continue;
        }
        out.push_str("  ");
        out.push_str(&opt_usage(sp, color));
        out.push('\n');
        let mut help = sp.help.to_string();
        if let Some(d) = sp.default {
            help.push_str(&format!(" [default: {}]", d));
        }
        if let Some(p) = sp.possible {
            help.push_str(&format!(" [possible values: {}]", p.join(", ")));
        }
        push_wrapped(&help, 10, wrapw, &mut out);
    }
    out
}

// ------------------------------------------------------------------ errors ---

fn arg_display(id: ArgId) -> String {
    let sp = specs().iter().find(|s| s.id == id).unwrap();
    match sp.value {
        Some(v) => format!("--{} <{}>", sp.long, v),
        None => format!("--{}", sp.long),
    }
}

fn arg_usage_color(id: ArgId) -> String {
    let sp = specs().iter().find(|s| s.id == id).unwrap();
    match sp.value {
        Some(v) => format!(
            "{}{}{}",
            literal(&format!("--{}", sp.long)),
            placeholder(" "),
            placeholder(&format!("<{}>", v))
        ),
        None => literal(&format!("--{}", sp.long)),
    }
}

fn footer(color: bool) -> String {
    if color {
        format!("\nFor more information, try '{}'.\n", literal("--help"))
    } else {
        "\nFor more information, try '--help'.\n".to_string()
    }
}

fn usage_default(name: &str, color: bool) -> String {
    if color {
        format!(
            "{} {} {} {}",
            header("Usage:"),
            literal(name),
            placeholder("[OPTIONS]"),
            placeholder("[FILE]")
        )
    } else {
        format!("Usage: {} [OPTIONS] [FILE]", name)
    }
}

fn usage_alternation(name: &str, color: bool) -> String {
    if color {
        format!(
            "{} {} {}",
            header("Usage:"),
            literal(name),
            placeholder(USAGE_ALTERNATION)
        )
    } else {
        format!("Usage: {} {}", name, USAGE_ALTERNATION)
    }
}

fn usage_args(name: &str, color: bool, args: &[String]) -> String {
    let mut s = if color {
        format!("{} {}", header("Usage:"), literal(name))
    } else {
        format!("Usage: {}", name)
    };
    for a in args {
        s.push(' ');
        s.push_str(a);
    }
    s
}

struct ErrCtx {
    name: String,
    color: bool,
    /// arguments set so far (in order)
    used: Vec<ArgId>,
    /// some argument or positional has been recorded (drives usage form)
    anything: bool,
    /// a flag or an attached value was recorded
    immediate: bool,
}

impl ErrCtx {
    fn unknown_form(&self, suggestion: bool) -> &'static str {
        if suggestion || self.anything {
            "alt"
        } else {
            "def"
        }
    }
    fn tmv_form(&self) -> &'static str {
        if self.immediate {
            "alt"
        } else {
            "args"
        }
    }
}

fn e_unexpected_argument(ctx: &ErrCtx, arg: &str, suggestion: Option<&str>) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "{} unexpected argument '{}' found\n",
        styled(ctx.color, "error:", err_styled),
        styled(ctx.color, arg, invalid_styled)
    ));
    match suggestion {
        Some(s) => out.push_str(&format!(
            "\n  {} a similar argument exists: '{}'\n",
            styled(ctx.color, "tip:", valid_styled),
            styled(ctx.color, s, valid_styled)
        )),
        None => out.push_str(&format!(
            "\n  {} to pass '{}' as a value, use '{}'\n",
            styled(ctx.color, "tip:", valid_styled),
            styled(ctx.color, arg, invalid_styled),
            styled(ctx.color, &format!("-- {}", arg), valid_styled)
        )),
    }
    out.push('\n');
    out.push_str(&match ctx.unknown_form(suggestion.is_some()) {
        "alt" => usage_alternation(&ctx.name, ctx.color),
        _ => usage_default(&ctx.name, ctx.color),
    });
    out.push('\n');
    out.push_str(&footer(ctx.color));
    out
}

fn e_extra_positional(ctx: &ErrCtx, arg: &str) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "{} unexpected argument '{}' found\n",
        styled(ctx.color, "error:", err_styled),
        styled(ctx.color, arg, invalid_styled)
    ));
    out.push('\n');
    out.push_str(&usage_default(&ctx.name, ctx.color));
    out.push('\n');
    out.push_str(&footer(ctx.color));
    out
}

fn e_too_many_values(ctx: &ErrCtx, val: &str, id: ArgId) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "{} unexpected value '{}' for '{}' found; no more were expected\n",
        styled(ctx.color, "error:", err_styled),
        styled(ctx.color, val, invalid_styled),
        styled(ctx.color, &format!("--{}", specs().iter().find(|s| s.id == id).unwrap().long), literal)
    ));
    out.push('\n');
    match ctx.tmv_form() {
        "alt" => out.push_str(&usage_alternation(&ctx.name, ctx.color)),
        _ => {
            if ctx.color {
                out.push_str(&format!(
                    "{} {} {}",
                    header("Usage:"),
                    literal(&ctx.name),
                    literal(&format!("--{}", specs().iter().find(|s| s.id == id).unwrap().long))
                ));
                out.push(' ');
                out.push_str(&placeholder("[FILE]"));
            } else {
                out.push_str(&format!(
                    "Usage: {} --{} [FILE]",
                    ctx.name,
                    specs().iter().find(|s| s.id == id).unwrap().long
                ));
            }
        }
    }
    out.push('\n');
    out.push_str(&footer(ctx.color));
    out
}

fn e_missing_value(ctx: &ErrCtx, id: ArgId) -> String {
    let sp = specs().iter().find(|s| s.id == id).unwrap();
    let mut out = String::new();
    out.push_str(&format!(
        "{} a value is required for '{}' but none was supplied\n",
        styled(ctx.color, "error:", err_styled),
        styled(ctx.color, &arg_display(id), invalid_styled)
    ));
    if let Some(p) = sp.possible {
        let list: Vec<String> = p.iter().map(|v| styled(ctx.color, v, valid_styled)).collect();
        out.push_str(&format!("  [possible values: {}]\n", list.join(", ")));
    }
    out.push_str(&footer(ctx.color));
    out
}

fn e_invalid_value(ctx: &ErrCtx, val: &str, id: ArgId, reason: Option<&str>) -> String {
    let sp = specs().iter().find(|s| s.id == id).unwrap();
    let mut out = String::new();
    match reason {
        Some(r) => out.push_str(&format!(
            "{} invalid value '{}' for '{}': {}\n",
            styled(ctx.color, "error:", err_styled),
            styled(ctx.color, val, invalid_styled),
            styled(ctx.color, &arg_display(id), literal),
            r
        )),
        None => {
            out.push_str(&format!(
                "{} invalid value '{}' for '{}'\n",
                styled(ctx.color, "error:", err_styled),
                styled(ctx.color, val, invalid_styled),
                styled(ctx.color, &arg_display(id), literal)
            ));
            if let Some(p) = sp.possible {
                let list: Vec<String> = p.iter().map(|v| styled(ctx.color, v, valid_styled)).collect();
                out.push_str(&format!("  [possible values: {}]\n", list.join(", ")));
                if let Some(s) = did_you_mean(val, p) {
                    out.push_str(&format!(
                        "\n  {} a similar value exists: '{}'\n",
                        styled(ctx.color, "tip:", valid_styled),
                        styled(ctx.color, s, valid_styled)
                    ));
                }
            }
        }
    }
    out.push_str(&footer(ctx.color));
    out
}

fn e_conflict(ctx: &ErrCtx, a: ArgId, b: ArgId) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "{} the argument '{}' cannot be used with '{}'\n",
        styled(ctx.color, "error:", err_styled),
        styled(ctx.color, &arg_display(a), invalid_styled),
        styled(ctx.color, &arg_display(b), invalid_styled)
    ));
    out.push('\n');
    let mut body: Vec<String> = Vec::new();
    for u in ctx.used.iter() {
        if *u == b {
            continue;
        }
        body.push(arg_usage_color(*u));
    }
    if ctx.color {
        body.push(placeholder("<FILE>"));
    } else {
        body.push("<FILE>".to_string());
    }
    out.push_str(&usage_args(
        &ctx.name,
        ctx.color,
        &body.iter().map(|s| if ctx.color { s.clone() } else { plain_of(s) }).collect::<Vec<_>>(),
    ));
    out.push('\n');
    out.push_str(&footer(ctx.color));
    out
}

/// strip the ANSI escapes from a styled string (used to build the plain form)
fn plain_of(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\u{1b}' {
            for c2 in chars.by_ref() {
                if c2 == 'm' {
                    break;
                }
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn e_multiple_use(ctx: &ErrCtx, id: ArgId) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "{} the argument '{}' cannot be used multiple times\n",
        styled(ctx.color, "error:", err_styled),
        styled(ctx.color, &arg_display(id), invalid_styled)
    ));
    out.push('\n');
    out.push_str(&usage_default(&ctx.name, ctx.color));
    out.push('\n');
    out.push_str(&footer(ctx.color));
    out
}

// ---------------------------------------------------------------- parsing ---

struct Raw {
    no_headers: bool,
    number: bool,
    tsv: bool,
    delimiter: Option<String>,
    style: Option<String>,
    padding: Option<String>,
    indent: Option<String>,
    sniff: Option<String>,
    header_align: Option<String>,
    body_align: Option<String>,
    disable_pager: bool,
    file: Option<String>,
}

impl Raw {
    fn new() -> Raw {
        Raw {
            no_headers: false,
            number: false,
            tsv: false,
            delimiter: None,
            style: None,
            padding: None,
            indent: None,
            sniff: None,
            header_align: None,
            body_align: None,
            disable_pager: false,
            file: None,
        }
    }
}

fn parse_usize(s: &str) -> Result<usize, &'static str> {
    if s.is_empty() {
        return Err("cannot parse integer from empty string");
    }
    let bytes = s.as_bytes();
    let mut i = 0usize;
    if bytes[0] == b'+' {
        i = 1;
        if bytes.len() == 1 {
            return Err("cannot parse integer from empty string");
        }
    }
    for b in &bytes[i..] {
        if !b.is_ascii_digit() {
            return Err("invalid digit found in string");
        }
    }
    let digits = &s[i..];
    let mut acc: u128 = 0;
    let mut overflow = false;
    for b in digits.bytes() {
        acc = acc * 10 + (b - b'0') as u128;
        if acc > usize::MAX as u128 {
            overflow = true;
            break;
        }
    }
    if overflow {
        return Err("number too large to fit in target type");
    }
    Ok(acc as usize)
}

fn parse_align(s: &str) -> Option<Align> {
    match s {
        "left" => Some(Align::Left),
        "center" => Some(Align::Center),
        "right" => Some(Align::Right),
        _ => None,
    }
}

fn is_known_option(tok: &str) -> bool {
    if tok == "--" {
        return true;
    }
    if let Some(rest) = tok.strip_prefix("--") {
        let name = rest.split('=').next().unwrap_or("");
        return specs().iter().any(|s| s.long == name);
    }
    if let Some(rest) = tok.strip_prefix('-') {
        if let Some(c) = rest.chars().next() {
            return specs().iter().any(|s| s.short == Some(c));
        }
    }
    false
}

fn spec_of(id: ArgId) -> &'static Spec {
    specs().iter().find(|s| s.id == id).unwrap()
}

pub fn parse(name: &str, argv: &[String], stdout_tty: bool, stderr_tty: bool) -> Outcome {
    let width = term_width();
    let mut raw = Raw::new();
    let mut used: Vec<ArgId> = Vec::new();
    let mut anything = false;
    let mut immediate = false;
    let mut pending: Option<(ArgId, Option<String>)> = None;
    let mut trailing = false;

    macro_rules! ctx {
        () => {
            ErrCtx {
                name: name.to_string(),
                color: stderr_tty,
                used: used.clone(),
                anything,
                immediate,
            }
        };
    }

    // react: check for duplicate use, convert, store
    macro_rules! react {
        ($id:expr, $val:expr) => {{
            let id: ArgId = $id;
            if used.contains(&id) {
                return Outcome::Error(e_multiple_use(&ctx!(), id));
            }
            match id {
                ArgId::Delimiter => {
                    let v: String = $val;
                    let mut it = v.chars();
                    match (it.next(), it.next()) {
                        (Some(_), None) => raw.delimiter = Some(v.clone()),
                        (None, _) => {
                            return Outcome::Error(e_invalid_value(
                                &ctx!(),
                                "",
                                id,
                                Some("cannot parse char from empty string"),
                            ))
                        }
                        _ => {
                            return Outcome::Error(e_invalid_value(
                                &ctx!(),
                                &v,
                                id,
                                Some("too many characters in string"),
                            ))
                        }
                    }
                }
                ArgId::Style => {
                    let v: String = $val;
                    if Style::from_str(&v).is_none() {
                        return Outcome::Error(e_invalid_value(&ctx!(), &v, id, None));
                    }
                    raw.style = Some(v.clone());
                }
                ArgId::HeaderAlign | ArgId::BodyAlign => {
                    let v: String = $val;
                    if parse_align(&v).is_none() {
                        return Outcome::Error(e_invalid_value(&ctx!(), &v, id, None));
                    }
                    if id == ArgId::HeaderAlign {
                        raw.header_align = Some(v.clone());
                    } else {
                        raw.body_align = Some(v.clone());
                    }
                }
                ArgId::Padding => {
                    let v: String = $val;
                    match parse_usize(&v) {
                        Ok(_) => raw.padding = Some(v.clone()),
                        Err(e) => return Outcome::Error(e_invalid_value(&ctx!(), &v, id, Some(e))),
                    }
                }
                ArgId::Indent => {
                    let v: String = $val;
                    match parse_usize(&v) {
                        Ok(_) => raw.indent = Some(v.clone()),
                        Err(e) => return Outcome::Error(e_invalid_value(&ctx!(), &v, id, Some(e))),
                    }
                }
                ArgId::Sniff => {
                    let v: String = $val;
                    match parse_usize(&v) {
                        Ok(_) => raw.sniff = Some(v.clone()),
                        Err(e) => return Outcome::Error(e_invalid_value(&ctx!(), &v, id, Some(e))),
                    }
                }
                _ => {}
            }
            used.push(id);
            anything = true;
            immediate = true;
        }};
    }

    // a value was supplied as a separate token: remember it, mark presence
    macro_rules! set_pending {
        ($id:expr, $val:expr) => {{
            pending = Some(($id, Some($val)));
            anything = true;
        }};
    }

    macro_rules! flush {
        () => {
            if let Some((id, val)) = pending.take() {
                match val {
                    Some(v) => react!(id, v),
                    None => {}
                }
            }
        };
    }

    // need a value from the next token
    macro_rules! take_next {
        ($id:expr) => {{
            if i + 1 < argv.len() {
                let nx = argv[i + 1].clone();
                if nx == "--" || is_known_option(&nx) {
                    return Outcome::Error(e_missing_value(&ctx!(), $id));
                } else if nx.starts_with('-') && nx.len() > 1 {
                    return Outcome::Error(e_unknown(&ctx!(), &nx, false));
                } else {
                    set_pending!($id, nx);
                    true
                }
            } else {
                return Outcome::Error(e_missing_value(&ctx!(), $id));
            }
        }};
    }

    macro_rules! e_unknown {
        ($ctx:expr, $arg:expr, $is_long:expr) => {{
            let suggestion = if $is_long {
                let stripped: String = $arg.trim_start_matches('-').to_string();
                did_you_mean(&stripped, &long_names())
            } else {
                None
            };
            e_unexpected_argument(&$ctx, &$arg, suggestion)
        }};
    }

    let mut i = 0usize;
    while i < argv.len() {
        let a = argv[i].clone();
        if trailing {
            flush!();
            if raw.file.is_some() {
                return Outcome::Error(e_extra_positional(&ctx!(), &a));
            }
            raw.file = Some(a);
            anything = true;
            i += 1;
            continue;
        }
        if a == "--" {
            flush!();
            trailing = true;
            i += 1;
            continue;
        }
        if a.starts_with("--") && a.len() > 2 {
            let body = &a[2..];
            let (lname, val) = match body.find('=') {
                Some(p) => (body[..p].to_string(), Some(body[p + 1..].to_string())),
                None => (body.to_string(), None),
            };
            let found = specs().iter().find(|s| s.long == lname).map(|s| s.id);
            let id = match found {
                Some(id) => id,
                None => {
                    return Outcome::Error(e_unknown(
                        &ctx!(),
                        &format!("--{}", lname),
                        true,
                    ))
                }
            };
            let takes_value = spec_of(id).value.is_some();
            if !takes_value {
                if let Some(v) = val {
                    return Outcome::Error(e_too_many_values(&ctx!(), &v, id));
                }
            }
            flush!();
            if takes_value {
                match val {
                    Some(v) => react!(id, v),
                    None => {
                        if take_next!(id) {
                            i += 1;
                            continue;
                        }
                    }
                }
            } else {
                if used.contains(&id) {
                    return Outcome::Error(e_multiple_use(&ctx!(), id));
                }
                used.push(id);
                anything = true;
                immediate = true;
                match id {
                    ArgId::NoHeaders => raw.no_headers = true,
                    ArgId::Number | ArgId::Seq => raw.number = true,
                    ArgId::Tsv => raw.tsv = true,
                    ArgId::DisablePager => raw.disable_pager = true,
                    ArgId::Help => return Outcome::Help(help_text(name, width, stdout_tty)),
                    ArgId::Version => return Outcome::Version(format!("{}\n", VERSION)),
                    _ => {}
                }
            }
            i += 1;
            continue;
        }
        if a.starts_with('-') && a.len() > 1 && a.as_bytes()[1] != b'-' {
            let chars: Vec<char> = a.chars().collect();
            let mut j = 1usize;
            let mut advanced = false;
            while j < chars.len() {
                let c = chars[j];
                let found = specs().iter().find(|s| s.short == Some(c)).map(|s| s.id);
                let id = match found {
                    Some(id) => id,
                    None => {
                        return Outcome::Error(e_unknown(
                            &ctx!(),
                            &format!("-{}", c),
                            false,
                        ))
                    }
                };
                flush!();
                let takes_value = spec_of(id).value.is_some();
                if takes_value {
                    let rest: String = chars[j + 1..].iter().collect();
                    if !rest.is_empty() {
                        let v = match rest.strip_prefix('=') {
                            Some(r) => r.to_string(),
                            None => rest,
                        };
                        react!(id, v);
                    } else {
                        if take_next!(id) {
                            i += 2;
                            advanced = true;
                        }
                    }
                    break;
                } else {
                    if used.contains(&id) {
                        return Outcome::Error(e_multiple_use(&ctx!(), id));
                    }
                    used.push(id);
                    anything = true;
                    immediate = true;
                    match id {
                        ArgId::NoHeaders => raw.no_headers = true,
                        ArgId::Number | ArgId::Seq => raw.number = true,
                        ArgId::Tsv => raw.tsv = true,
                        ArgId::DisablePager => raw.disable_pager = true,
                        ArgId::Help => return Outcome::Help(help_text(name, width, stdout_tty)),
                        ArgId::Version => return Outcome::Version(format!("{}\n", VERSION)),
                        _ => {}
                    }
                    j += 1;
                }
            }
            if !advanced {
                i += 1;
            }
            continue;
        }
        // value for a pending option, or a positional
        flush!();
        if let Some((id, val)) = pending.as_mut() {
            if val.is_none() {
                *val = Some(a);
                anything = true;
                i += 1;
                continue;
            }
        }
        if raw.file.is_some() {
            return Outcome::Error(e_extra_positional(&ctx!(), &a));
        }
        raw.file = Some(a);
        anything = true;
        i += 1;
    }
    flush!();

    // conflicts
    if raw.tsv && raw.delimiter.is_some() {
        let first = used
            .iter()
            .find(|u| **u == ArgId::Tsv || **u == ArgId::Delimiter)
            .copied()
            .unwrap();
        let second = if first == ArgId::Tsv {
            ArgId::Delimiter
        } else {
            ArgId::Tsv
        };
        return Outcome::Error(e_conflict(&ctx!(), first, second));
    }

    let mut cfg = Config::default();
    cfg.no_headers = raw.no_headers;
    cfg.number = raw.number;
    cfg.tsv = raw.tsv;
    if let Some(d) = raw.delimiter {
        cfg.delimiter = d.chars().next().unwrap();
    }
    if let Some(s) = raw.style {
        cfg.style = Style::from_str(&s).unwrap();
    }
    if let Some(p) = raw.padding {
        cfg.padding = parse_usize(&p).unwrap();
    }
    if let Some(v) = raw.indent {
        cfg.indent = parse_usize(&v).unwrap();
    }
    if let Some(s) = raw.sniff {
        cfg.sniff = parse_usize(&s).unwrap();
    }
    if let Some(h) = raw.header_align {
        cfg.header_align = parse_align(&h).unwrap();
    }
    if let Some(b) = raw.body_align {
        cfg.body_align = parse_align(&b).unwrap();
    }
    cfg.disable_pager = raw.disable_pager;
    cfg.file = raw.file;
    Outcome::Run(Box::new(cfg))
}

pub fn term_width() -> usize {
    const TIOCGWINSZ: u64 = 0x5413;
    #[repr(C)]
    struct WinSize {
        rows: u16,
        cols: u16,
        x: u16,
        y: u16,
    }
    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
    }
    for fd in [1i32, 2, 0].iter() {
        let mut size = WinSize { rows: 0, cols: 0, x: 0, y: 0 };
        unsafe {
            if ioctl(*fd, TIOCGWINSZ, &mut size as *mut WinSize) == 0 && size.cols > 0 {
                return size.cols as usize;
            }
        }
    }
    if let Ok(v) = std::env::var("COLUMNS") {
        if let Ok(n) = v.parse::<usize>() {
            return n;
        }
    }
    100
}
