mod cli;
mod csv;
mod pager;
mod table;
mod tables;
mod width;

use std::io::Read;
use std::io::Write;

fn fail(msg: &str) -> ! {
    eprintln!("csview: {}", msg);
    std::process::exit(1);
}

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    let name = argv
        .first()
        .map(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| "csview".to_string());
    let stdout_tty = pager::stdout_is_tty();
    let stderr_tty = pager::stderr_is_tty();
    let rest: Vec<String> = argv.iter().skip(1).cloned().collect();
    match cli::parse(&name, &rest, stdout_tty, stderr_tty) {
        cli::Outcome::Help(h) => {
            print!("{}", h);
            std::process::exit(0);
        }
        cli::Outcome::Version(v) => {
            print!("{}", v);
            std::process::exit(0);
        }
        cli::Outcome::Error(e) => {
            eprint!("{}", e);
            std::process::exit(2);
        }
        cli::Outcome::Run(cfg) => run(&cfg),
    }
}

fn read_input(path: &Option<String>) -> Vec<u8> {
    match path {
        None | Some(p) if p == "-" => {
            let mut buf = Vec::new();
            match std::io::stdin().read_to_end(&mut buf) {
                Ok(_) => buf,
                Err(e) => fail(&e.to_string()),
            }
        }
        Some(p) => match std::fs::File::open(p) {
            Ok(mut f) => {
                let mut buf = Vec::new();
                match f.read_to_end(&mut buf) {
                    Ok(_) => buf,
                    Err(e) => fail(&e.to_string()),
                }
            }
            Err(e) => fail(&e.to_string()),
        },
    }
}

fn run(cfg: &cli::Config) {
    let data = read_input(&cfg.file);
    let delim: u8 = if cfg.tsv {
        b'\t'
    } else {
        let mut b = [0u8; 4];
        let s = cfg.delimiter.to_string();
        b.copy_from_slice(&s.as_bytes()[..s.len().min(4)]);
        s.bytes().next().unwrap_or(b',')
    };
    let (records, err) = csv::records(data, delim);
    if let Some(e) = err {
        fail(&e.to_string());
    }
    // split header / body
    let mut headers: Vec<String> = Vec::new();
    let mut rows: Vec<Vec<String>> = Vec::new();
    if cfg.no_headers {
        rows = records;
    } else {
        let mut it = records.into_iter();
        if let Some(h) = it.next() {
            headers = h;
        }
        rows = it.collect();
    }
    if cfg.number {
        let width = if rows.is_empty() {
            1
        } else {
            format!("{}", rows.len()).len()
        };
        let _ = width;
        if cfg.no_headers {
            for (i, r) in rows.iter_mut().enumerate() {
                r.insert(0, format!("{}", i + 1));
            }
        } else {
            headers.insert(0, "#".to_string());
            for (i, r) in rows.iter_mut().enumerate() {
                r.insert(0, format!("{}", i + 1));
            }
        }
    }
    let ncols = rows.iter().map(|r| r.len()).chain(std::iter::once(headers.len())).max().unwrap_or(0);
    let mut headers = headers;
    headers.resize(ncols, String::new());
    for r in rows.iter_mut() {
        r.resize(ncols, String::new());
    }
    // sniff column widths
    let limit = if cfg.sniff == 0 { usize::MAX } else { cfg.sniff };
    let mut widths = vec![0usize; ncols];
    if !cfg.no_headers {
        for (i, h) in headers.iter().enumerate() {
            widths[i] = width::width(h);
        }
    }
    for r in rows.iter().take(limit) {
        for (i, c) in r.iter().enumerate() {
            let w = width::width(c);
            if w > widths[i] {
                widths[i] = w;
            }
        }
    }
    let t = table::Table { headers, rows, widths };
    let out = table::render(
        &t,
        cfg.style,
        cfg.padding,
        cfg.indent,
        cfg.header_align,
        cfg.body_align,
    );
    if !cfg.disable_pager && pager::stdout_is_tty() {
        if let Some(rows) = pager::term_rows() {
            let lines = out.matches('\n').count();
            if lines >= rows {
                if pager::page(&out) {
                    return;
                }
            }
        }
    }
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
}
