//! Simple pager support: pipe the table into `less` when the output does not
//! fit on the terminal.

use std::io::Write;
use std::os::unix::io::AsRawFd;

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn execvp(file: *const i8, argv: *const *const i8) -> i32;
    fn isatty(fd: i32) -> i32;
    fn dup(fd: i32) -> i32;
    fn dup2(src: i32, dst: i32) -> i32;
    fn close(fd: i32) -> i32;
    fn pipe(fds: *mut i32) -> i32;
    fn fork() -> i32;
    fn waitpid(pid: i32, status: *mut i32, options: i32) -> i32;
    fn _exit(code: i32) -> !;
}

const TIOCGWINSZ: u64 = 0x5413;

#[repr(C)]
struct WinSize {
    rows: u16,
    cols: u16,
    x: u16,
    y: u16,
}

pub fn stdout_is_tty() -> bool {
    unsafe { isatty(1) == 1 }
}

pub fn stderr_is_tty() -> bool {
    unsafe { isatty(2) == 1 }
}

pub fn term_rows() -> Option<usize> {
    let mut size = WinSize { rows: 0, cols: 0, x: 0, y: 0 };
    unsafe {
        if ioctl(1, TIOCGWINSZ, &mut size as *mut WinSize) == 0 && size.rows > 0 {
            return Some(size.rows as usize);
        }
    }
    None
}

fn find_less() -> Option<std::path::PathBuf> {
    let path = std::env::var("PATH").ok()?;
    for dir in path.split(':') {
        if dir.is_empty() {
            continue;
        }
        let p = std::path::Path::new(dir).join("less");
        if p.is_file() {
            return Some(p);
        }
    }
    None
}

fn cstr(s: &str) -> Vec<u8> {
    let mut v = s.as_bytes().to_vec();
    v.push(0);
    v
}

/// Pipe `content` into `less`. Returns true when the pager was used.
pub fn page(content: &str) -> bool {
    let less = match find_less() {
        Some(l) => l,
        None => return false,
    };
    let stdin_save = unsafe { dup(0) };
    if stdin_save < 0 {
        return false;
    }
    let mut fds = [0i32; 2];
    if unsafe { pipe(fds.as_mut_ptr()) } != 0 {
        unsafe {
            close(stdin_save);
        }
        return false;
    }
    let pid = unsafe { fork() };
    if pid < 0 {
        unsafe {
            close(fds[0]);
            close(fds[1]);
            close(stdin_save);
        }
        return false;
    }
    if pid == 0 {
        // child: run less with our pipe as stdin
        unsafe {
            close(fds[1]);
            dup2(fds[0], 0);
            close(fds[0]);
            let prog = cstr(less.to_str().unwrap_or("less"));
            let arg0 = cstr("less");
            let mut argv: Vec<*const i8> = Vec::new();
            argv.push(arg0.as_ptr() as *const i8);
            argv.push(std::ptr::null());
            let mut env: Vec<*const i8> = Vec::new();
            for (k, v) in std::env::vars() {
                if k == "LESS" {
                    continue;
                }
                let mut e = format!("{}={}", k, v).into_bytes();
                e.push(0);
                env.push(e.as_ptr() as *const i8);
            }
            let lessenv = cstr("LESS=-SF");
            env.push(lessenv.as_ptr() as *const i8);
            env.push(std::ptr::null());
            execvp(prog.as_ptr() as *const i8, argv.as_ptr());
            _exit(127);
        }
    }
    // parent
    unsafe {
        close(fds[0]);
        dup2(fds[1], 0);
        close(fds[1]);
    }
    {
        let mut stdout = std::io::stdout();
        let _ = stdout.write_all(content.as_bytes());
        let _ = stdout.flush();
    }
    unsafe {
        // restore stdin and close the write end so less sees EOF
        dup2(stdin_save, 0);
        close(stdin_save);
        let mut status = 0i32;
        let _ = waitpid(pid, &mut status, 0);
    }
    true
}
