struct Parser<'a> {
    name: &'a str,
    color: bool,
    argv: &'a [std::ffi::OsString],
    raw: Raw,
    used: Vec<ArgId>,
    anything: bool,
    immediate: bool,
    pending: Option<(ArgId, Option<std::ffi::OsString>)>,
    width: usize,
    stdout_tty: bool,
