impl<'a> Parser<'a> {
    fn ctx(&self) -> ErrCtx {
        ErrCtx {
            name: self.name.to_string(),
            color: self.color,
            used: self.used.clone(),
            anything: self.anything,
            immediate: self.immediate,
        }
    }

    fn invalid_utf8(&self) -> String {
        let mut out = String::new();
        out.push_str(&format!(
            "{} invalid UTF-8 was detected in one or more arguments\n",
            styled(self.color, "error:", err_styled)
        ));
        out.push('\n');
        out.push_str(&usage_default(&self.name, self.color));
        out.push('\n');
        out.push_str(&footer(self.color));
        out
    }

    /// convert and store the value of `id`
    fn react(&mut self, id: ArgId, val: &std::ffi::OsStr) -> Result<(), String> {
        if self.used.contains(&id) {
            return Err(e_multiple_use(&self.ctx(), id));
        }
        let needs_str = matches!(
            id,
            ArgId::Delimiter | ArgId::Padding | ArgId::Indent | ArgId::Sniff
        );
        if needs_str && val.to_str().is_none() {
            return Err(self.invalid_utf8());
        }
        let s = val.to_string_lossy().into_owned();
        match id {
            ArgId::Delimiter => {
                let mut it = s.chars();
                match (it.next(), it.next()) {
                    (Some(_), None) => self.raw.delimiter = Some(s.clone()),
                    (None, _) => {
                        return Err(e_invalid_value(
                            &self.ctx(),
                            "",
                            id,
                            Some("cannot parse char from empty string"),
                        ))
                    }
                    _ => {
                        return Err(e_invalid_value(
                            &self.ctx(),
                            &s,
                            id,
                            Some("too many characters in string"),
                        ))
                    }
                }
            }
            ArgId::Style => {
                if Style::from_str(&s).is_none() {
                    return Err(e_invalid_value(&self.ctx(), &s, id, None));
                }
                self.raw.style = Some(s.clone());
            }
            ArgId::HeaderAlign | ArgId::BodyAlign => {
                if parse_align(&s).is_none() {
                    return Err(e_invalid_value(&self.ctx(), &s, id, None));
                }
                if id == ArgId::HeaderAlign {
                    self.raw.header_align = Some(s.clone());
                } else {
                    self.raw.body_align = Some(s.clone());
                }
            }
            ArgId::Padding => match parse_usize(&s) {
                Ok(_) => self.raw.padding = Some(s.clone()),
                Err(e) => return Err(e_invalid_value(&self.ctx(), &s, id, Some(e))),
            },
            ArgId::Indent => match parse_usize(&s) {
                Ok(_) => self.raw.indent = Some(s.clone()),
                Err(e) => return Err(e_invalid_value(&self.ctx(), &s, id, Some(e))),
            },
            ArgId::Sniff => match parse_usize(&s) {
                Ok(_) => self.raw.sniff = Some(s.clone()),
                Err(e) => return Err(e_invalid_value(&self.ctx(), &s, id, Some(e))),
            },
            _ => {}
        }
        self.used.push(id);
        self.anything = true;
        self.immediate = true;
        Ok(())
    }

    fn flush(&mut self) -> Result<(), String> {
        if let Some((id, val)) = self.pending.take() {
            if let Some(v) = val {
                self.react(id, &v)?;
            }
        }
        Ok(())
    }

    fn set_flag(&mut self, id: ArgId) -> Result<(), String> {
        if self.used.contains(&id) {
            return Err(e_multiple_use(&self.ctx(), id));
        }
        self.used.push(id);
        self.anything = true;
        self.immediate = true;
        Ok(())
    }

    /// expect the value in the next token; returns true when consumed
    fn take_next(&mut self, i: usize, id: ArgId) -> Result<bool, String> {
        if i + 1 < self.argv.len() {
            let nx = self.argv[i + 1].clone();
            let s = nx.to_string_lossy().into_owned();
            if s == "--" || is_known_option(&s) {
                return Err(e_missing_value(&self.ctx(), id));
