            if s.starts_with('-') && s.len() > 1 {
                return Err(e_unexpected_argument(&self.ctx(), &s, None));
            }
            self.pending = Some((id, Some(nx)));
            self.anything = true;
            Ok(true)
        } else {
            Err(e_missing_value(&self.ctx(), id))
        }
    }

    fn unknown(&self, arg: &str, is_long: bool) -> String {
