                    if let Err(e) = p.set_flag(id) {
                        return Outcome::Error(e);
                    }
                    match id {
                        ArgId::NoHeaders => p.raw.no_headers = true,
                        ArgId::Number | ArgId::Seq => p.raw.number = true,
                        ArgId::Tsv => p.raw.tsv = true,
                        ArgId::DisablePager => p.raw.disable_pager = true,
                        ArgId::Help => return Outcome::Help(help_text(name, width, stdout_tty)),
                        ArgId::Version => return Outcome::Version(format!("{}\n", VERSION)),
