                p.anything = true;
                i += 1;
                continue;
            }
        }
        p.flush()?;
        if p.raw.file.is_some() {
            return Outcome::Error(e_extra_positional(&p.ctx(), &s));
        }
        p.raw.file = Some(a);
        p.anything = true;
        i += 1;
    }
    if let Err(e) = p.flush() {
        return Outcome::Error(e);
    }
    if p.raw.tsv && p.raw.delimiter.is_some() {
        let first = p
            .used
            .iter()
            .find(|u| **u == ArgId::Tsv || **u == ArgId::Delimiter)
            .copied()
            .unwrap();
        let second = if first == ArgId::Tsv {
            ArgId::Delimiter
        } else {
            ArgId::Tsv
        };
        return Outcome::Error(e_conflict(&p.ctx(), first, second));
    }
    let mut cfg = Config::default();
    cfg.no_headers = p.raw.no_headers;
    cfg.number = p.raw.number;
    cfg.tsv = p.raw.tsv;
    if let Some(d) = p.raw.delimiter {
        cfg.delimiter = d.chars().next().unwrap();
    }
    if let Some(s) = p.raw.style {
        cfg.style = Style::from_str(&s).unwrap();
    }
    if let Some(v) = p.raw.padding {
        cfg.padding = parse_usize(&v).unwrap();
    }
    if let Some(v) = p.raw.indent {
        cfg.indent = parse_usize(&v).unwrap();
    }
    if let Some(v) = p.raw.sniff {
        cfg.sniff = parse_usize(&v).unwrap();
    }
    if let Some(h) = p.raw.header_align {
        cfg.header_align = parse_align(&h).unwrap();
    }
    if let Some(b) = p.raw.body_align {
        cfg.body_align = parse_align(&b).unwrap();
    }
    cfg.disable_pager = p.raw.disable_pager;
    cfg.file = p.raw.file.map(|f| f.to_string_lossy().into_owned());
    cfg.file_os = p.raw.file;
    Outcome::Run(Box::new(cfg))
}

