//! Table rendering.

use crate::width::width;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Align {
    Left,
    Center,
    Right,
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Style {
    None,
    Ascii,
    Ascii2,
    Sharp,
    Rounded,
    Reinforced,
    Markdown,
    Grid,
}

impl Style {
    pub fn from_str(s: &str) -> Option<Style> {
        match s {
            "none" => Some(Style::None),
            "ascii" => Some(Style::Ascii),
            "ascii2" => Some(Style::Ascii2),
            "sharp" => Some(Style::Sharp),
            "rounded" => Some(Style::Rounded),
            "reinforced" => Some(Style::Reinforced),
            "markdown" => Some(Style::Markdown),
            "grid" => Some(Style::Grid),
            _ => None,
        }
    }
}

struct Borders {
    left: Option<char>,
    right: Option<char>,
    sep: Option<char>,
    h: char,
    tl: char,
    tm: char,
    tr: char,
    ml: char,
    mm: char,
    mr: char,
    bl: char,
    bm: char,
    br: char,
    /// separator row between every pair of body rows
    all_rows: bool,
    /// draw the top and bottom border rows
    outer: bool,
}

impl Style {
    fn borders(&self) -> Borders {
        let sharp = Borders {
            left: Some('\u{2502}'),
            right: Some('\u{2502}'),
            sep: Some('\u{2502}'),
            h: '\u{2500}',
            tl: '\u{250c}',
            tm: '\u{252c}',
            tr: '\u{2510}',
            ml: '\u{251c}',
            mm: '\u{253c}',
            mr: '\u{2524}',
            bl: '\u{2514}',
            bm: '\u{2534}',
            br: '\u{2518}',
            all_rows: false,
            outer: true,
        };
        match self {
            Style::None => Borders {
                left: None,
                right: None,
                sep: None,
                h: ' ',
                tl: ' ',
                tm: ' ',
                tr: ' ',
                ml: ' ',
                mm: ' ',
                mr: ' ',
                bl: ' ',
                bm: ' ',
                br: ' ',
                all_rows: false,
                outer: false,
            },
            Style::Ascii => Borders {
                left: Some('|'),
                right: Some('|'),
                sep: Some('|'),
                h: '-',
                tl: '+',
                tm: '+',
                tr: '+',
                ml: '+',
                mm: '+',
                mr: '+',
                bl: '+',
                bm: '+',
                br: '+',
                all_rows: false,
                outer: true,
            },
            Style::Ascii2 => Borders {
                left: Some(' '),
                right: Some(' '),
                sep: Some('|'),
                h: '-',
                tl: '+',
                tm: '+',
                tr: '+',
                ml: ' ',
                mm: '+',
                mr: ' ',
                bl: '+',
                bm: '+',
                br: '+',
                all_rows: false,
                outer: false,
            },
            Style::Sharp => sharp,
            Style::Rounded => Borders {
                tl: '\u{256d}',
                tr: '\u{256e}',
                bl: '\u{2570}',
                br: '\u{256f}',
                ..sharp
            },
            Style::Reinforced => Borders {
                tl: '\u{250f}',
                tr: '\u{2513}',
                bl: '\u{2517}',
                br: '\u{251b}',
                ..sharp
            },
            Style::Markdown => Borders {
                left: Some('|'),
                right: Some('|'),
                sep: Some('|'),
                h: '-',
                tl: '|',
                tm: '|',
                tr: '|',
                ml: '|',
                mm: '|',
                mr: '|',
                bl: '|',
                bm: '|',
                br: '|',
                all_rows: false,
                outer: false,
            },
            Style::Grid => Borders {
                all_rows: true,
                ..sharp
            },
        }
    }
}

/// Truncate a string so that it does not occupy more than `max` columns.
fn truncate(s: &str, max: usize) -> String {
    if width(s) <= max {
        return s.to_string();
    }
    let mut out = String::new();
    let mut acc = 0usize;
    for c in s.chars() {
        let w = width(&c.to_string());
        if acc + w > max {
            break;
        }
        acc += w;
        out.push(c);
    }
    out
}

fn pad(s: &str, w: usize, align: Align) -> String {
    let sw = width(s);
    if sw >= w {
        return s.to_string();
    }
    let extra = w - sw;
    let mut r = String::new();
    match align {
        Align::Left => {
            r.push_str(s);
            for _ in 0..extra {
                r.push(' ');
            }
        }
        Align::Right => {
            for _ in 0..extra {
                r.push(' ');
            }
            r.push_str(s);
        }
        Align::Center => {
            let l = extra / 2;
            let rgt = extra - l;
            for _ in 0..l {
                r.push(' ');
            }
            r.push_str(s);
            for _ in 0..rgt {
                r.push(' ');
            }
        }
    }
    r
}

pub struct Table {
    pub headers: Vec<String>,
    pub rows: Vec<Vec<String>>,
    pub widths: Vec<usize>,
    pub has_headers: bool,
}

pub fn render(
    t: &Table,
    style: Style,
    padding: usize,
    indent: usize,
    header_align: Align,
    body_align: Align,
) -> String {
    let b = style.borders();
    let ncols = t.widths.len();
    let ind: String = " ".repeat(indent);
    let cellw: Vec<usize> = t.widths.iter().map(|w| w + 2 * padding).collect();
    let mut out = String::new();

    let mut emit = |s: &str, out: &mut String| {
        out.push_str(&ind);
        out.push_str(s);
        out.push('\n');
    };

    let rule = |left: char, mid: char, right: char, out: &mut String| {
        let mut s = String::new();
        s.push(left);
        for (i, w) in cellw.iter().enumerate() {
            if i > 0 {
                s.push(mid);
            }
            for _ in 0..*w {
                s.push(b.h);
            }
        }
        s.push(right);
        emit(&s, out);
    };

    let border = |which: Option<char>, out: &mut String| -> bool {
        match which {
            Some(c) => {
                out.push(c);
                true
            }
            None => false,
        }
    };

    let row_line = |cells: &Vec<String>, align: Align, out: &mut String| {
        let mut s = String::new();
        let mut started = border(b.left, &mut s);
        for (i, c) in cells.iter().enumerate() {
            if i > 0 {
                started = border(b.sep, &mut s) || started;
            }
            for _ in 0..padding {
                s.push(' ');
            }
            let tc = if i < t.widths.len() {
                truncate(c, t.widths[i])
            } else {
                c.clone()
            };
            let w = if i < t.widths.len() { t.widths[i] } else { width(c) };
            s.push_str(&pad(&tc, w, align));
            for _ in 0..padding {
                s.push(' ');
            }
        }
        let _ = started;
        border(b.right, &mut s);
        emit(&s, out);
    };

    if b.outer && ncols > 0 {
        rule(b.tl, b.tm, b.tr, &mut out);
    }
    if t.has_headers {
        row_line(&t.headers, header_align, &mut out);
    }
    if t.has_headers && !t.rows.is_empty() && ncols > 0 {
        rule(b.ml, b.mm, b.mr, &mut out);
    }
    for (i, r) in t.rows.iter().enumerate() {
        row_line(r, body_align, &mut out);
        if b.all_rows && i + 1 < t.rows.len() && ncols > 0 {
            rule(b.ml, b.mm, b.mr, &mut out);
        }
    }
    if b.outer && ncols > 0 {
        rule(b.bl, b.bm, b.br, &mut out);
    }
    out
}
