/// Truncate a string so that it does not occupy more than `max` columns.
fn truncate(s: &str, max: usize) -> String {
    if width(s) <= max {
        return s.to_string();
    }
    let mut out = String::new();
    let mut acc = 0usize;
    for c in s.chars() {
        let w = width(&c.to_string());
        if acc + w > max {
            break;
        }
        acc += w;
        out.push(c);
    }
    out
}

fn pad(s: &str, w: usize, align: Align) -> String {
    let sw = width(s);
    if sw >= w {
        return s.to_string();
    }
    let extra = w - sw;
    let mut r = String::new();
    match align {
        Align::Left => {
            r.push_str(s);
            for _ in 0..extra {
                r.push(' ');
            }
        }
        Align::Right => {
            for _ in 0..extra {
                r.push(' ');
            }
            r.push_str(s);
        }
        Align::Center => {
            let l = extra / 2;
            let rgt = extra - l;
            for _ in 0..l {
                r.push(' ');
            }
            r.push_str(s);
            for _ in 0..rgt {
                r.push(' ');
            }
        }
    }
    r
}

pub struct Table {
    pub headers: Vec<String>,
    pub rows: Vec<Vec<String>>,
    pub widths: Vec<usize>,
    pub has_headers: bool,
}

pub fn render(
    t: &Table,
    style: Style,
    padding: usize,
    indent: usize,
    header_align: Align,
    body_align: Align,
) -> String {
    let b = style.borders();
    let ncols = t.widths.len();
    let ind: String = " ".repeat(indent);
    let cellw: Vec<usize> = t.widths.iter().map(|w| w + 2 * padding).collect();
    let mut out = String::new();

    let mut emit = |s: &str, out: &mut String| {
        out.push_str(&ind);
        out.push_str(s);
        out.push('\n');
    };

    let rule = |left: char, mid: char, right: char, out: &mut String| {
        let mut s = String::new();
        s.push(left);
        for (i, w) in cellw.iter().enumerate() {
            if i > 0 {
                s.push(mid);
            }
            for _ in 0..*w {
                s.push(b.h);
            }
        }
        s.push(right);
        emit(&s, out);
    };

    let border = |which: Option<char>, out: &mut String| -> bool {
        match which {
            Some(c) => {
                out.push(c);
                true
            }
            None => false,
        }
    };

    let row_line = |cells: &Vec<String>, align: Align, out: &mut String| {
        let mut s = String::new();
        let mut started = border(b.left, &mut s);
        for (i, c) in cells.iter().enumerate() {
            if i > 0 {
                started = border(b.sep, &mut s) || started;
            }
            for _ in 0..padding {
                s.push(' ');
            }
            let tc = if i < t.widths.len() {
                truncate(c, t.widths[i])
            } else {
                c.clone()
            };
            let w = if i < t.widths.len() { t.widths[i] } else { width(c) };
            s.push_str(&pad(&tc, w, align));
            for _ in 0..padding {
                s.push(' ');
            }
        }
        let _ = started;
        border(b.right, &mut s);
        emit(&s, out);
    };

    if b.outer && ncols > 0 {
        rule(b.tl, b.tm, b.tr, &mut out);
    }
    if t.has_headers {
        row_line(&t.headers, header_align, &mut out);
    }
    if t.has_headers && !t.rows.is_empty() && ncols > 0 {
        rule(b.ml, b.mm, b.mr, &mut out);
    }
    for (i, r) in t.rows.iter().enumerate() {
        row_line(r, body_align, &mut out);
        if b.all_rows && i + 1 < t.rows.len() && ncols > 0 {
            rule(b.ml, b.mm, b.mr, &mut out);
        }
    }
    if b.outer && ncols > 0 {
        rule(b.bl, b.bm, b.br, &mut out);
    }
    out
}
